INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-business-ethics-fundamentals-assessment', c.id, 'Module 1: Business Ethics Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The principles and standards that guide right and wrong conduct in a professional setting"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"integrity","acceptableAnswers":["Integrity"]},{"id":"q4","type":"scenario","answer":"Raise it through the appropriate reporting channel at your workplace"},{"id":"q5","type":"matching","pairs":[{"left":"Rationalising small rule-breaking","right":"Treating minor dishonest acts as harmless"},{"left":"Pressure to hit unrealistic targets","right":"Creates an incentive to cut ethical corners"},{"left":"A culture of silence","right":"Employees are afraid to report wrongdoing"},{"left":"Inconsistent enforcement of rules","right":"Some people are held to different standards than others"}]},{"id":"q6","type":"multiple-choice","answer":"Pressure to bend the rules in order to hit targets"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Pause and identify exactly what\'s at stake","Check the situation against company policy and values","Raise the concern through the appropriate channel","Follow up to confirm it was actually addressed"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-business-ethics-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-employee-ethics-assessment', c.id, 'Module 2: Employee Ethics — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A situation where two or more values or obligations genuinely conflict"},{"id":"q2","type":"fill-blank","answer":"rationalization","acceptableAnswers":["rationalisation","rationalizations","rationalisations"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Cite the source, or rewrite it fully in your own words and understanding"},{"id":"q5","type":"matching","pairs":[{"left":"Motivated ignorance","right":"Deliberately avoiding finding out something you\'d rather not know"},{"left":"Appropriate use of company assets","right":"Using work resources only for legitimate business purposes"},{"left":"Reporting unethical behaviour","right":"Raising a genuine concern through the correct internal channel"},{"left":"Negative gossip","right":"Sharing damaging, unverified talk about a colleague"}]},{"id":"q6","type":"true-false","answer":"False"},{"id":"q7","type":"multiple-choice","answer":"It lets you avoid responsibility while still benefiting from wrongdoing you chose not to investigate"},{"id":"q8","type":"ordering","items":["Confirm what you actually witnessed, and note the facts","Check your organisation\'s reporting policy or channel","Report it through that proper channel","Cooperate with any follow-up review respectfully"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-employee-ethics';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-leadership-on-ethics-assessment', c.id, 'Module 3: Leadership on Ethics — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It sets the tone and standard that the rest of the team follows"},{"id":"q2","type":"fill-blank","answer":"code of conduct","acceptableAnswers":["employee code of conduct","codes of conduct"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Disclose the relationship and ensure the evaluation uses fair, consistent, documented criteria"},{"id":"q5","type":"matching","pairs":[{"left":"Making ethics part of company culture","right":"Embedding values into everyday decisions, not just a poster on the wall"},{"left":"Evaluating performance fairly","right":"Using consistent, documented, unbiased criteria"},{"left":"Developing ethical employees","right":"Coaching and modelling good judgement over time"},{"left":"Managing conflicts of interest","right":"Disclosing and controlling situations where personal and professional interests compete"}]},{"id":"q6","type":"true-false","answer":"False"},{"id":"q7","type":"multiple-choice","answer":"Weigh the values and people affected, consult where appropriate, and be ready to explain the reasoning"},{"id":"q8","type":"ordering","items":["Set and communicate a clear code of conduct","Model the standard consistently as a leader","Coach and give feedback in real situations as they arise","Evaluate and recognise ethical behaviour fairly over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-leadership-on-ethics';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-driving-your-career-assessment', c.id, 'Module 1: Driving your Career — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Taking deliberate ownership of your goals, growth, and opportunities instead of waiting for them to come to you"},{"id":"q2","type":"fill-blank","answer":"plan","acceptableAnswers":["Plan"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Increasing your value at work","right":"Building skills and delivering results that matter to your organisation"},{"left":"Personal brand at work","right":"The reputation and impression you consistently create through your work and conduct"},{"left":"Preparing for a performance review","right":"Gathering evidence of your accomplishments ahead of time"},{"left":"Transferring jobs internally","right":"Moving to a different role or team within the same company"}]},{"id":"q5","type":"scenario","answer":"Prepare specific evidence of your increased contributions and results, then raise it directly with your manager at an appropriate time"},{"id":"q6","type":"multiple-choice","answer":"Deciding whether your career growth comes through leading others or through deepening your own expertise"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Reflect on your goals, strengths, and interests","Set specific, achievable career goals","Identify the concrete steps and skills needed to reach them","Review and adjust the plan regularly as you grow"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-driving-your-career';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-assessing-your-strengths-and-skills-assessment', c.id, 'Module 2: Assessing your Strengths and Skills — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"fill-blank","answer":"core values","acceptableAnswers":["values","Core Values","Values"]},{"id":"q3","type":"multiple-choice","answer":"Intentionally applying what you\'re naturally good at to create more value and satisfaction in your role"},{"id":"q4","type":"matching","pairs":[{"left":"Understanding your strengths","right":"Recognising what you\'re naturally good at and do well"},{"left":"Matching career to interests","right":"Pursuing work that genuinely engages what you enjoy"},{"left":"Seeking feedback","right":"Proactively asking others for honest input on your performance"},{"left":"Receiving feedback","right":"Genuinely listening to and processing feedback once it\'s given"}]},{"id":"q5","type":"scenario","answer":"Listen without getting defensive, ask clarifying questions, and reflect on how to apply it"},{"id":"q6","type":"multiple-choice","answer":"It helps you evaluate whether a role, team, or company genuinely fits what matters to you"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Reflect honestly on what you\'re good at and what you enjoy","Define the core values that matter most to you","Seek feedback from others to check your self-assessment","Apply what you\'ve learned to guide real career decisions"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-assessing-your-strengths-and-skills';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-finding-a-new-job-assessment', c.id, 'Module 3: Finding a New Job — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Consistent lack of growth opportunities and misalignment with your values over a sustained period"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"interview","acceptableAnswers":["Interview"]},{"id":"q4","type":"matching","pairs":[{"left":"A resume","right":"Summarises your experience and qualifications concisely"},{"left":"A cover letter","right":"Explains your specific motivation and fit for this role"},{"left":"Interview preparation","right":"Getting ready to confidently discuss your experience and fit"},{"left":"Deciding on remote work","right":"Evaluating whether that working style genuinely suits you"}]},{"id":"q5","type":"scenario","answer":"Honestly assess your own work style, need for structure, and social needs before deciding"},{"id":"q6","type":"multiple-choice","answer":"Using multiple methods — networking, job boards, and targeted applications — rather than relying on just one"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Recognise genuine signs it\'s time for a change","Update your resume and prepare tailored cover letters","Search and apply through multiple channels","Prepare thoroughly and perform well in interviews"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-finding-a-new-job';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-new-professional-assessment', c.id, 'Module 4: New Professional — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A structured set of goals for your first three months in a new role, broken into phases"},{"id":"q2","type":"fill-blank","answer":"weakness","acceptableAnswers":["incompetence","failure"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"A successful work attitude","right":"Approaching your role with openness, initiative, and professionalism"},{"left":"Being an effective teammate","right":"Reliably contributing to and supporting the success of the group"},{"left":"Connecting with coworkers","right":"Building genuine working relationships beyond just task coordination"},{"left":"Training new coworkers","right":"Helping someone newer than you learn the role effectively"}]},{"id":"q5","type":"scenario","answer":"Make a genuine attempt, note your specific questions, and ask for help as soon as someone is available"},{"id":"q6","type":"multiple-choice","answer":"Actively seeking feedback and applying it to improve"},{"id":"q7","type":"ordering","items":["Focus on learning the role and building relationships in your first week","Set structured goals with a 30/60/90-day plan","Contribute actively as an effective, reliable teammate","Build lasting confidence by taking on new challenges over time"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-4-new-professional';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-networking-assessment', c.id, 'Module 5: Networking — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Building genuine, mutually beneficial relationships with people in your professional field"},{"id":"q3","type":"fill-blank","answer":"elevator","acceptableAnswers":["Elevator"]},{"id":"q4","type":"matching","pairs":[{"left":"Navigating a networking event","right":"Confidently starting and moving between conversations with new people"},{"left":"An elevator pitch","right":"A brief, clear introduction of who you are and what you offer"},{"left":"Developing a network","right":"Actively building new professional relationships over time"},{"left":"Maintaining a network","right":"Keeping existing professional relationships genuinely active"}]},{"id":"q5","type":"scenario","answer":"Wait for a natural pause, introduce yourself briefly, and show genuine interest in what they\'re discussing"},{"id":"q6","type":"multiple-choice","answer":"It can lead to mentorship, new ideas, referrals, and opportunities you wouldn\'t encounter otherwise"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Prepare a clear, genuine elevator pitch","Attend events or settings where you can meet relevant people","Follow up after making a new connection","Maintain the relationship with occasional, genuine contact over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-networking';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-mentoring-in-the-workplace-assessment', c.id, 'Module 6: Mentoring in the Workplace — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A more experienced person who offers guidance, perspective, and support for your growth"},{"id":"q2","type":"fill-blank","answer":"mentee","acceptableAnswers":["Mentee"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Finding a mentor","right":"Identifying and approaching someone whose experience and guidance you value"},{"left":"Being a model mentee","right":"Actively contributing to and making the most of the mentoring relationship"},{"left":"Mentoring others","right":"Offering your own experience and guidance to someone less experienced"},{"left":"A common mentoring challenge","right":"A recurring obstacle, like mismatched expectations, that can strain the relationship"}]},{"id":"q5","type":"scenario","answer":"Raise the pattern directly and openly, and clarify what you both expect from the relationship going forward"},{"id":"q6","type":"multiple-choice","answer":"Identifying someone whose experience you respect and approaching them with a clear, specific ask"},{"id":"q7","type":"ordering","items":["Identify and approach a potential mentor with a clear ask","Agree on expectations for the relationship","Show up prepared and follow through as a model mentee","Address any challenges directly as they come up"]},{"id":"q8","type":"true-false","answer":"True"}]' FROM `courses` c WHERE c.`slug` = 'module-6-mentoring-in-the-workplace';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-professional-etiquette-assessment', c.id, 'Module 7: Professional Etiquette — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"fill-blank","answer":"formal","acceptableAnswers":["Formal"]},{"id":"q3","type":"multiple-choice","answer":"A clear subject line, a concise message, and an appropriate tone for the audience"},{"id":"q4","type":"matching","pairs":[{"left":"Workplace professionalism","right":"Consistently conducting yourself in a reliable, respectful, work-appropriate way"},{"left":"Business email etiquette","right":"Writing clear, appropriately toned, well-structured messages"},{"left":"Business phone etiquette","right":"Communicating clearly and courteously when neither party can see the other"},{"left":"Formal vs. informal communication","right":"Matching your tone and language to the audience and context"}]},{"id":"q5","type":"scenario","answer":"Use a clear subject line, a formal and respectful tone, and a concise, specific request"},{"id":"q6","type":"multiple-choice","answer":"Speaking clearly, identifying yourself promptly, and actively listening without interrupting"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Clarify the purpose of the email before writing it","Write a clear, specific subject line","Keep the message concise and appropriately toned","Proofread before sending"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-professional-etiquette';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-working-relationships-assessment', c.id, 'Module 8: Working Relationships — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Consistent communication, reliability, and understanding their priorities and expectations"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"conversation","acceptableAnswers":["discussion","talk"]},{"id":"q4","type":"matching","pairs":[{"left":"Strong coworker relationships","right":"Built through mutual respect, reliability, and genuine collaboration"},{"left":"Strong relationship with your boss","right":"Built through clear communication and understanding their expectations"},{"left":"Repairing a broken relationship","right":"Honestly addressing what went wrong and rebuilding trust over time"},{"left":"Working with someone you don\'t like","right":"Maintaining professionalism and respect despite a personal disconnect"}]},{"id":"q5","type":"scenario","answer":"Initiate an honest, calm conversation to clear up the miscommunication directly"},{"id":"q6","type":"ordering","items":["Reflect honestly on what happened and your own part in it","Initiate a calm, honest conversation with the other person","Listen to their perspective without becoming defensive","Agree on how to move forward and follow through consistently"]},{"id":"q7","type":"multiple-choice","answer":"Stay respectful and focused on shared work goals, regardless of personal feelings"},{"id":"q8","type":"true-false","answer":"True"}]' FROM `courses` c WHERE c.`slug` = 'module-8-working-relationships';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-9-overcoming-challenges-assessment', c.id, 'Module 9: Overcoming Challenges — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Give yourself space to process it, then focus energy on updating your materials and network"},{"id":"q3","type":"fill-blank","answer":"apology","acceptableAnswers":["Apology"]},{"id":"q4","type":"matching","pairs":[{"left":"Feeling unmotivated","right":"Identifying the real cause and adjusting your approach or goals"},{"left":"Coping with workplace change","right":"Staying adaptable and focusing on what you can control"},{"left":"Fear of failure","right":"Reframing failure as a normal part of learning and growth"},{"left":"Impostor syndrome","right":"Recognising the feeling as distorted and grounding yourself in real evidence of your ability"}]},{"id":"q5","type":"scenario","answer":"Focus on what you can control, stay adaptable, and seek clarity on the parts that are still unclear"},{"id":"q6","type":"multiple-choice","answer":"Consistently delivering strong results and communicating your contributions clearly"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Acknowledge the mistake honestly, without minimising it","Offer a sincere apology to anyone affected","Take concrete action to fix or limit the damage","Reflect on what you\'ll do differently going forward"]}]' FROM `courses` c WHERE c.`slug` = 'module-9-overcoming-challenges';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-change-management-fundamentals-assessment', c.id, 'Module 1: Change Management Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The structured approach to preparing, supporting, and helping people through organisational change"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"model","acceptableAnswers":["Model","framework"]},{"id":"q4","type":"matching","pairs":[{"left":"Types of organisational change","right":"Distinguishes change by its scope and purpose, like incremental versus transformational"},{"left":"Change management models","right":"Provides a structured framework for planning and guiding change"},{"left":"Best practices","right":"Proven approaches that increase the likelihood of change succeeding"},{"left":"Common challenges","right":"Recurring obstacles, like resistance, that tend to arise during change"}]},{"id":"q5","type":"multiple-choice","answer":"Communicating clearly and involving employees early in the process"},{"id":"q6","type":"scenario","answer":"Proactively communicate the reasons for the change and create space for employees to raise concerns"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Identify the type and scope of the change needed","Select a change management model or approach to guide it","Communicate the change clearly and involve employees early","Monitor for challenges and address resistance as it arises"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-change-management-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-change-management-models-assessment', c.id, 'Module 2: Change Management Models — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Unfreeze, Change, Refreeze"},{"id":"q2","type":"fill-blank","answer":"7","acceptableAnswers":["seven","Seven"]},{"id":"q3","type":"true-false","answer":"True"},{"id":"q4","type":"matching","pairs":[{"left":"Lewin\'s 3-Step Model","right":"A simple three-stage view of unfreezing, changing, and refreezing"},{"left":"Kotter\'s 8-Step Model","right":"A detailed, sequential roadmap for leading large-scale change"},{"left":"Kubler-Ross Framework","right":"Mapping the emotional stages people go through during change"},{"left":"The Satir Model","right":"Describing how performance typically dips before improving during change"}]},{"id":"q5","type":"multiple-choice","answer":"Guiding large-scale organisational change through a detailed, sequential process"},{"id":"q6","type":"scenario","answer":"The Satir Model\'s idea that performance often dips before it improves during change"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Unfreeze the current state and prepare people for change","Make the actual change","Refreeze the new state so it becomes the new normal"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-change-management-models';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-the-change-management-process-assessment', c.id, 'Module 3: The Change Management Process — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Clearly explaining why the change is necessary and what happens if nothing changes"},{"id":"q3","type":"fill-blank","answer":"vision","acceptableAnswers":["Vision"]},{"id":"q4","type":"matching","pairs":[{"left":"Making the case for change","right":"Establishes why the change is genuinely necessary"},{"left":"Developing a vision","right":"Paints a clear, motivating picture of the desired future state"},{"left":"Creating an action plan","right":"Turns the vision into concrete, assigned, time-bound steps"},{"left":"Measuring effectiveness","right":"Confirms whether the change actually achieved its intended results"}]},{"id":"q5","type":"scenario","answer":"Encourage them to seek clarity on specifically what\'s changing for their role, and to focus on what they can control"},{"id":"q6","type":"multiple-choice","answer":"It shows whether the change actually achieved its intended outcomes, and informs future adjustments"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Make the case for why change is needed","Develop and communicate a clear vision for the change","Create a detailed change action plan","Measure the effectiveness of the change once implemented"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-the-change-management-process';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-communicating-change-assessment', c.id, 'Module 4: Communicating Change — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A clear plan for what to communicate, when, through which channels, and to whom"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"buy-in","acceptableAnswers":["Buy-in","buyin"]},{"id":"q4","type":"matching","pairs":[{"left":"A communication strategy","right":"A deliberate plan for what, when, and how to communicate about the change"},{"left":"Employee buy-in","right":"Genuine commitment and support for the change, not just compliance"},{"left":"Effective change communication","right":"Clear, honest, and consistent messaging throughout the process"},{"left":"Two-way communication","right":"Creating real opportunities for employees to ask questions and respond"}]},{"id":"q5","type":"scenario","answer":"The communication likely needs to be more frequent, consistent, and open to employee questions"},{"id":"q6","type":"multiple-choice","answer":"Being honest about both the benefits and the challenges of the change"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Identify the different audiences and what they need to know","Craft clear, honest key messages for the change","Choose the right channels and timing to deliver them","Create ongoing opportunities for feedback and questions"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-communicating-change';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-leading-through-change-assessment', c.id, 'Module 5: Leading Through Change — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"fill-blank","answer":"empowering","acceptableAnswers":["Empowering"]},{"id":"q3","type":"multiple-choice","answer":"Modelling calm, adaptable behaviour that the team can follow"},{"id":"q4","type":"matching","pairs":[{"left":"Modelling calm and adaptability","right":"Showing the team steady, flexible behaviour they can follow"},{"left":"Empowering employees","right":"Giving employees real trust and autonomy to make decisions during change"},{"left":"Transparent leadership","right":"Sharing honest, timely information rather than withholding it"},{"left":"Supporting the team emotionally","right":"Acknowledging how people are feeling, not just what they need to do"}]},{"id":"q5","type":"scenario","answer":"Reassure them and deliberately empower them with clear boundaries so they regain confidence in making decisions"},{"id":"q6","type":"multiple-choice","answer":"Communicate frequently and honestly, even when you don\'t have all the answers"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Model calm, adaptable behaviour yourself","Communicate honestly and frequently with the team","Empower employees with real autonomy and support","Recognise and reinforce positive progress as the change takes hold"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-leading-through-change';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-managing-change-in-time-of-crisis-assessment', c.id, 'Module 6: Managing Change in Time of Crisis — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"There\'s typically far less time to prepare, plan, and communicate before acting"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"crisis","acceptableAnswers":["Crisis"]},{"id":"q4","type":"matching","pairs":[{"left":"Leading during unexpected change","right":"Making sound decisions quickly with limited information and time"},{"left":"Building team adaptability","right":"Developing the team\'s capacity to respond well to future disruption"},{"left":"Supporting employees in a crisis","right":"Genuinely attending to people\'s wellbeing, not just their output"},{"left":"Turning crisis into opportunity","right":"Identifying genuine positive change or improvement that can come out of a crisis"}]},{"id":"q5","type":"scenario","answer":"Communicate honestly about what\'s known and unknown, and prioritise genuine support for employees\' wellbeing"},{"id":"q6","type":"multiple-choice","answer":"Honestly identifying what the crisis revealed and using it to make a genuine improvement"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Assess the situation quickly with the information available","Communicate honestly with the team about what\'s known","Support employees\' wellbeing throughout the disruption","Reflect afterward to identify any genuine opportunity for positive change"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-managing-change-in-time-of-crisis';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-communication-fundamentals-assessment', c.id, 'Module 1: Communication Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Something disrupts the message between sender and receiver — a barrier, unclear wording, or a mismatch in understanding"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"written","acceptableAnswers":["Written"]},{"id":"q4","type":"scenario","answer":"A face-to-face or video conversation, where tone and nonverbal cues can support the message"},{"id":"q5","type":"matching","pairs":[{"left":"Physical barrier","right":"Noise, distance, or a closed door getting in the way of a message"},{"left":"Perceptual barrier","right":"Two people interpreting the same message differently based on their own assumptions"},{"left":"Emotional barrier","right":"Fear, distrust, or strong feelings that make someone hold back or misread a message"},{"left":"Language barrier","right":"Jargon, unclear wording, or a language gap that blocks understanding"},{"left":"Cultural barrier","right":"Differing norms or values causing the same message to be read differently"}]},{"id":"q6","type":"multiple-choice","answer":"It often carries as much or more meaning than the words themselves — tone, posture, and expression all send signals"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Clarify the purpose and urgency of your message","Consider your audience and the context they\'re in","Weigh the trade-off between speed and richness of the medium","Select the medium and send your message"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-communication-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-empathy-assessment', c.id, 'Module 2: Empathy — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The ability to understand and share in another person\'s feelings and perspective"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"Empathy","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Listen fully and acknowledge how they\'re feeling before offering any advice"},{"id":"q5","type":"matching","pairs":[{"left":"Stereotyping or bias","right":"Assuming you already know how someone feels based on a group they belong to"},{"left":"Time pressure","right":"Rushing past someone\'s feelings because you feel you don\'t have time to engage"},{"left":"Emotional exhaustion","right":"Being too depleted yourself to genuinely take on someone else\'s feelings"},{"left":"Limited exposure to different perspectives","right":"Struggling to relate to an experience very different from your own"}]},{"id":"q6","type":"multiple-choice","answer":"Deliberately seeking out perspectives and experiences different from your own"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Listen fully without interrupting","Acknowledge and validate what the other person is feeling","Ask clarifying questions to understand fully","Respond thoughtfully, offering support if it\'s wanted"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-empathy';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-verbal-communication-assessment', c.id, 'Module 3: Verbal Communication — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"An open question"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"paraphrasing","acceptableAnswers":["Paraphrasing","reflecting"]},{"id":"q4","type":"scenario","answer":"Ask an open, genuine question about them or the shared context you\'re both in"},{"id":"q5","type":"matching","pairs":[{"left":"Active listening","right":"Giving your full attention and engaging with what\'s being said, not just hearing it"},{"left":"Paraphrasing","right":"Restating what you heard in your own words to confirm understanding"},{"left":"Minimal encouragers","right":"Small verbal or nonverbal cues, like nodding or \\"I see,\\" that show you\'re following"},{"left":"Avoiding interruption","right":"Letting the speaker finish their thought before you respond"}]},{"id":"q6","type":"multiple-choice","answer":"Clarify and rectify the mistake as soon as you notice it"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Start the conversation with a genuine, open question","Listen actively and ask clarifying open or closed questions as needed","Rectify and clarify promptly if a misunderstanding occurs","End the conversation on a clear, positive note"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-verbal-communication';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-meetings-assessment', c.id, 'Module 4: Meetings — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Give the meeting a clear structure and set of objectives so it stays on track"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"facilitation","acceptableAnswers":["facilitating"]},{"id":"q4","type":"scenario","answer":"Acknowledge both viewpoints, refocus the group on the shared objective, and manage the exchange calmly"},{"id":"q5","type":"matching","pairs":[{"left":"Setting a meeting agenda","right":"Giving the meeting clear structure and objectives in advance"},{"left":"Group facilitation","right":"Actively guiding discussion and encouraging balanced participation"},{"left":"Building consensus","right":"Helping the group reach a decision most people genuinely support"},{"left":"Managing conflict in meetings","right":"Keeping disagreement constructive instead of letting it derail the discussion"}]},{"id":"q6","type":"multiple-choice","answer":"Hearing different perspectives and working toward a decision most people can support"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Set and share a clear agenda before the meeting","Open the meeting by restating its objective","Facilitate discussion and manage any conflict constructively","Summarise decisions and agreed next steps at the close"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-meetings';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-presentations-assessment', c.id, 'Module 5: Presentations — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Your presentation\'s objective — what you want the audience to think, feel, or do afterward"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"body","acceptableAnswers":["middle","main body"]},{"id":"q4","type":"scenario","answer":"Stay calm, acknowledge the question genuinely, and answer honestly — or say you\'ll follow up if you don\'t know"},{"id":"q5","type":"matching","pairs":[{"left":"One idea per slide","right":"Avoiding cramming multiple unrelated points onto a single slide"},{"left":"Minimal text, more visuals","right":"Letting images or charts carry meaning instead of dense paragraphs"},{"left":"Consistent design","right":"Using the same fonts, colours, and layout style throughout"},{"left":"Clear data visualisation","right":"Choosing a chart type that makes the key number obvious at a glance"}]},{"id":"q6","type":"multiple-choice","answer":"Simplify the chart and clearly highlight the one key takeaway"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Define your presentation objective","Structure your content into an opening, body, and conclusion","Design clear, simple visual aids","Practise your delivery and prepare for likely questions"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-presentations';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-negotiation-and-persuasion-assessment', c.id, 'Module 6: Negotiation and Persuasion — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Negotiation involves reaching a mutual agreement through give-and-take; persuasion is about influencing someone\'s beliefs or actions"},{"id":"q2","type":"fill-blank","answer":"Integrative","acceptableAnswers":[]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Prepare evidence of your value, understand your manager\'s constraints, and aim for an outcome that works for both sides"},{"id":"q5","type":"matching","pairs":[{"left":"Reciprocity","right":"People feel inclined to return a favour they\'ve received"},{"left":"Social proof","right":"People look to what others are already doing to decide what\'s right"},{"left":"Authority","right":"People are more easily persuaded by a credible, expert source"},{"left":"Scarcity","right":"People value something more when it seems limited or hard to get"}]},{"id":"q6","type":"multiple-choice","answer":"Anchoring"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Prepare by researching your position and the other party\'s likely interests","Open with a clear, justifiable position","Exchange information and explore each side\'s underlying interests","Bargain and make considered concessions","Reach and confirm a final agreement"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-negotiation-and-persuasion';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-writing-well-assessment', c.id, 'Module 7: Writing Well — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Being clear, before you start writing, about exactly what you want the reader to know or do afterward"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"proofreading","acceptableAnswers":["Proofreading"]},{"id":"q4","type":"scenario","answer":"Keep the core facts consistent, but adjust tone, framing, and level of detail for each audience"},{"id":"q5","type":"matching","pairs":[{"left":"Writing for your audience","right":"Adapting tone and detail to who\'s actually going to read the message"},{"left":"Structuring your writing","right":"Organising content so key information is easy to find and follow"},{"left":"Editing","right":"Reviewing and improving content, clarity, and structure"},{"left":"Proofreading","right":"Catching surface-level spelling, grammar, and punctuation errors"}]},{"id":"q6","type":"multiple-choice","answer":"Leading with the key point or conclusion, then supporting detail"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Define your purpose and audience","Draft content structured around your key point","Edit for clarity, structure, and tone","Proofread for grammar, spelling, and punctuation"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-writing-well';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-communicating-in-difficult-situations-assessment', c.id, 'Module 8: Communicating in Difficult Situations — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Address the specific behaviour directly and calmly with them, focusing on impact rather than character"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"escalated to HR","acceptableAnswers":["reported to HR","escalated","involve HR","reported to human resources"]},{"id":"q4","type":"scenario","answer":"Ask for a private conversation to understand their perspective and calmly share the impact it\'s having"},{"id":"q5","type":"matching","pairs":[{"left":"Assertive","right":"Expressing your own needs clearly while still respecting others"},{"left":"Passive","right":"Avoiding expressing your own needs or opinions to keep the peace"},{"left":"Aggressive","right":"Pushing your own needs while disregarding others\' feelings or views"},{"left":"Passive-aggressive","right":"Expressing frustration indirectly rather than stating it openly"}]},{"id":"q6","type":"multiple-choice","answer":"Prepare what you want to say in advance and focus on the specific issue, not the person"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Prepare and get clear on your own goal for the conversation","Choose an appropriate time and private setting","State the facts and your feelings calmly, without blame","Listen genuinely to the other person\'s perspective","Agree on clear next steps"]}]' FROM `courses` c WHERE c.`slug` = 'module-8-communicating-in-difficult-situations';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-critical-thinking-fundamentals-assessment', c.id, 'Module 1: Critical Thinking Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The disciplined process of objectively analysing and evaluating information before forming a judgment"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"bias","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"A weak inductive generalisation drawn from a single, limited data point"},{"id":"q5","type":"matching","pairs":[{"left":"Critical thinking","right":"The disciplined, objective process of analysing information before judging it"},{"left":"Deductive reasoning","right":"Moving from a general principle to a certain, specific conclusion"},{"left":"Inductive reasoning","right":"Moving from specific observations to a probable general conclusion"},{"left":"Cognitive bias","right":"A systematic, often unconscious distortion in judgment"}]},{"id":"q6","type":"multiple-choice","answer":"A better question that strengthens critical thinking by testing the strength of your own belief"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Clearly identify the question or problem","Gather relevant information and evidence","Question assumptions and consider alternative explanations","Draw a reasoned conclusion based on the evidence"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-critical-thinking-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-thinking-in-the-workplace-assessment', c.id, 'Module 2: Thinking in the Workplace — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Is supported by clear evidence and sound reasoning that logically connects to its conclusion"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"fallacy","acceptableAnswers":["fallacies"]},{"id":"q4","type":"scenario","answer":"Appeal to tradition — assuming something is correct or best simply because it\'s how things have always been done"},{"id":"q5","type":"matching","pairs":[{"left":"Appeal to tradition","right":"Assuming something is correct because it\'s always been done that way"},{"left":"Strong workplace argument","right":"Supported by clear evidence and logically sound reasoning"},{"left":"Developing employees\' critical thinking","right":"Coaching others to question assumptions and reason through problems themselves"},{"left":"Logical fallacy","right":"A flaw in reasoning that undermines an argument\'s validity"}]},{"id":"q6","type":"multiple-choice","answer":"Deliberately seeking out perspectives that challenge your initial assumption before deciding"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Clearly state the claim you\'re making","Gather credible evidence that supports it","Check the reasoning for logical fallacies or gaps","Anticipate and address the strongest counterargument"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-thinking-in-the-workplace';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-critical-thinking-and-information-literacy-assessment', c.id, 'Module 3: Critical Thinking and Information Literacy — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It\'s transparent about its evidence and methodology, and can be corroborated by other credible sources"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"satire","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Verify it against other credible, independent sources before trusting or sharing it"},{"id":"q5","type":"matching","pairs":[{"left":"Fact","right":"A statement that can be objectively verified as true or false"},{"left":"Opinion","right":"A personal belief or judgment that isn\'t objectively verifiable"},{"left":"Satire","right":"Content using exaggeration or irony for commentary, not meant as literal news"},{"left":"Fake news","right":"Fabricated content deliberately presented as genuine, factual news"}]},{"id":"q6","type":"multiple-choice","answer":"Ask whether the statement could, in principle, be checked against objective evidence"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Check the source\'s identity, credentials, and track record","Look for cited evidence or original data behind the claim","Compare the claim against other independent, credible sources","Decide how much confidence to place in it based on what you find"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-critical-thinking-and-information-literacy';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-customer-service-fundamentals-assessment', c.id, 'Module 1: Customer Service Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It directly shapes whether customers stay loyal, return, and recommend the business to others"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"exceeding","acceptableAnswers":["Exceeding"]},{"id":"q4","type":"scenario","answer":"Match their friendly tone while still handling the billing issue accurately and efficiently"},{"id":"q5","type":"matching","pairs":[{"left":"Personable service","right":"Making the interaction feel warm, friendly, and human"},{"left":"Professional service","right":"Handling the interaction competently, accurately, and respectfully"},{"left":"Meeting expectations","right":"Delivering what the customer assumed they\'d get"},{"left":"Exceeding expectations","right":"Delivering more value or care than the customer assumed they\'d get"}]},{"id":"q6","type":"multiple-choice","answer":"Helping a customer troubleshoot a problem with a product they already bought"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Understand what the customer actually expects from the interaction","Deliver a response that fully meets that expectation","Look for a genuine, low-effort way to go beyond it","Confirm the customer is satisfied before ending the interaction"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-customer-service-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-customer-service-skills-assessment', c.id, 'Module 2: Customer Service Skills — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Clear communication, patience, empathy, and problem-solving"},{"id":"q2","type":"fill-blank","answer":"fatigue","acceptableAnswers":["Fatigue"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Recognising personality type","right":"Noticing how a customer communicates so you can adapt your approach"},{"left":"An analytical customer","right":"Tends to want facts, detail, and a logical explanation"},{"left":"An expressive or relational customer","right":"Tends to want warmth, rapport, and reassurance"},{"left":"Adapting your style","right":"Adjusting your tone and pace to match what the customer responds to"}]},{"id":"q5","type":"scenario","answer":"Recognise the signs of empathy fatigue and use a healthy coping strategy, like a short break, before continuing"},{"id":"q6","type":"multiple-choice","answer":"Clearly understanding exactly what the problem is from the customer\'s perspective"},{"id":"q7","type":"ordering","items":["Ask questions to fully understand the problem","Identify possible causes or solutions","Walk the customer through the fix, or apply it for them","Confirm the issue is actually resolved"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-2-customer-service-skills';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-customer-communication-basics-assessment', c.id, 'Module 3: Customer Communication Basics — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Referencing relevant details specific to that customer, like their history or preferences"},{"id":"q3","type":"fill-blank","answer":"active","acceptableAnswers":["Active"]},{"id":"q4","type":"matching","pairs":[{"left":"A good conversation starter","right":"Opens the interaction warmly and puts the customer at ease"},{"left":"Expressing empathy","right":"Shows the customer their feelings and situation are genuinely understood"},{"left":"Soliciting feedback","right":"Actively asks the customer for their honest opinion of the experience"},{"left":"Ending the conversation well","right":"Leaves the customer clear on next steps and feeling genuinely helped"}]},{"id":"q5","type":"scenario","answer":"Acknowledge their frustration genuinely, thank them for the feedback, and explain what you\'ll do about it"},{"id":"q6","type":"multiple-choice","answer":"\\"That sounds really frustrating — I can understand why you\'re upset about this.\\""},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Open with a warm, genuine conversation starter","Actively listen to understand the customer\'s need","Respond with empathy and a clear solution","Confirm satisfaction and close the conversation properly"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-customer-communication-basics';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-customer-communication-channels-assessment', c.id, 'Module 4: Customer Communication Channels — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Providing a consistent, connected experience across all the channels a customer might use"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"switching","acceptableAnswers":["Switching"]},{"id":"q4","type":"matching","pairs":[{"left":"Phone calls","right":"Use a clear, warm tone since the customer can\'t see your expression"},{"left":"Email","right":"Write clearly and completely, since there\'s no back-and-forth in real time"},{"left":"Live chat","right":"Reply promptly and keep messages concise"},{"left":"Social media","right":"Respond publicly with care, since the exchange may be visible to others"}]},{"id":"q5","type":"multiple-choice","answer":"Self-service support, like a help centre or FAQ page"},{"id":"q6","type":"scenario","answer":"Respond publicly with empathy and an offer to resolve it, then move detailed account info to a private channel"},{"id":"q7","type":"ordering","items":["Confirm which new channel best fits the customer\'s need","Carry over the relevant context or history to the new channel","Let the customer know what to expect next","Continue the interaction without asking them to repeat themselves"]},{"id":"q8","type":"multiple-choice","answer":"Speaking clearly, actively listening, and controlling pace and tone since there\'s no visual cues"}]' FROM `courses` c WHERE c.`slug` = 'module-4-customer-communication-channels';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-team-management-assessment', c.id, 'Module 5: Team Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A deliberate plan that defines standards, priorities, and how the team will deliver consistent service"},{"id":"q2","type":"fill-blank","answer":"churn","acceptableAnswers":["Churn"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Contact centre management","right":"Overseeing the people, processes, and technology behind customer support"},{"left":"Customer retention","right":"Keeping existing customers continuing to do business with you"},{"left":"Proactive customer service","right":"Reaching out to help before the customer has to ask"},{"left":"Measuring service performance","right":"Using metrics to track how well the team is actually serving customers"}]},{"id":"q5","type":"multiple-choice","answer":"A help desk or ticketing system to track and manage customer issues"},{"id":"q6","type":"scenario","answer":"Review how tickets are being prioritised and assigned, and adjust the process to clear the backlog"},{"id":"q7","type":"ordering","items":["Define what great service looks like for your customers","Set clear standards and priorities for the team","Equip and empower the team to meet those standards","Measure performance and adjust the strategy over time"]},{"id":"q8","type":"multiple-choice","answer":"Anticipating a customer\'s need and reaching out before they have to contact support"}]' FROM `courses` c WHERE c.`slug` = 'module-5-team-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-culture-sensitivity-assessment', c.id, 'Module 6: Culture Sensitivity — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Communication norms, expectations, and comfort levels can differ meaningfully across cultures, affecting how service is experienced"},{"id":"q3","type":"fill-blank","answer":"bias","acceptableAnswers":["Bias"]},{"id":"q4","type":"matching","pairs":[{"left":"Cultural sensitivity","right":"Being aware of and respectful toward cultural differences"},{"left":"Cross-cultural communication","right":"Adapting how you communicate to be clearly understood across cultural differences"},{"left":"Cultural bias","right":"An unfair, often unconscious assumption based on someone\'s cultural background"},{"left":"Exceptional cross-cultural service","right":"Delivering consistently great service regardless of a customer\'s cultural background"}]},{"id":"q5","type":"scenario","answer":"Ask open, patient questions to gently understand their actual concern, without assuming they\'re being evasive"},{"id":"q6","type":"multiple-choice","answer":"Actively notice and question assumptions you make about customers based on accent, name, or background"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Recognise there may be a cultural difference shaping the interaction","Adapt your tone, pace, or directness accordingly","Check that your message was understood as intended","Reflect on the interaction to improve next time"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-culture-sensitivity';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-difficult-situations-assessment', c.id, 'Module 7: Difficult Situations — Test Your Knowledge', 80, '[{"id":"q1","type":"scenario","answer":"Stay calm, let them vent briefly, and acknowledge their frustration before working toward a solution"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"feelings","acceptableAnswers":["Feeling","perception","reaction"]},{"id":"q4","type":"matching","pairs":[{"left":"An effective apology","right":"Genuinely owns the mistake and focuses on making it right"},{"left":"Handling a refund request","right":"Following a fair, clear process while listening to the customer\'s reason"},{"left":"Saying no to a customer","right":"Declining a request clearly and respectfully, with a real explanation"},{"left":"Gaining control of a conversation","right":"Steering a difficult exchange back toward a productive resolution"}]},{"id":"q5","type":"multiple-choice","answer":"A gap between what they expected and what they actually experienced"},{"id":"q6","type":"scenario","answer":"Weigh the customer\'s history and the situation, and consider reasonable flexibility to retain their trust"},{"id":"q7","type":"ordering","items":["Acknowledge the customer\'s concern to lower the tension","Ask a focused question to understand the real issue","Redirect the conversation toward a concrete next step","Confirm the customer agrees with the way forward"]},{"id":"q8","type":"true-false","answer":"True"}]' FROM `courses` c WHERE c.`slug` = 'module-7-difficult-situations';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-online-security-fundamentals-assessment', c.id, 'Module 1: Online Security Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The practice of protecting systems, networks, and data from digital attacks, damage, or unauthorised access"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"rogue","acceptableAnswers":["fake","evil twin"]},{"id":"q4","type":"scenario","answer":"Verify their identity through another channel before accepting, or decline if you can\'t confirm who they are"},{"id":"q5","type":"matching","pairs":[{"left":"Secure browsing","right":"Practices like checking for HTTPS and avoiding suspicious links to browse safely"},{"left":"Public Wi-Fi risk","right":"Data can be intercepted on unsecured shared networks"},{"left":"Safe social media use","right":"Verifying identities and limiting personal information shared publicly"},{"left":"Security incident response","right":"The steps to take immediately after discovering a breach or compromise"}]},{"id":"q6","type":"multiple-choice","answer":"Checking that a site uses HTTPS and avoiding clicking unfamiliar or suspicious links"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Recognise and confirm signs that something is wrong","Report it immediately through the correct channel","Contain the issue where possible, e.g. change a compromised password","Follow guidance from IT/security on next steps and monitor for further issues"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-online-security-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-how-to-protect-your-data-assessment', c.id, 'Module 2: How to Protect your Data — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Protecting sensitive information from being accessed or disclosed to people who aren\'t authorised to see it"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"multifactor","acceptableAnswers":["multi-factor","multi factor","two-factor","2-factor"]},{"id":"q4","type":"scenario","answer":"Lock your screen (or log out) before leaving your desk, even briefly"},{"id":"q5","type":"matching","pairs":[{"left":"Confidentiality","right":"Protecting sensitive information from unauthorised access or disclosure"},{"left":"Strong, unique passwords","right":"Reduce the risk of one breach compromising multiple accounts"},{"left":"Multifactor authentication","right":"Requires a second form of verification beyond just a password"},{"left":"Removable media security","right":"Controlling and protecting USB drives and other portable storage from data loss or infection"}]},{"id":"q6","type":"multiple-choice","answer":"If lost or stolen, anyone who finds it can access the data with no further barrier"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Create a long, unique password not reused from another account","Avoid predictable patterns like personal dates or common words","Store it securely, such as in a reputable password manager","Update it promptly if you suspect it may have been exposed"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-how-to-protect-your-data';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-social-engineering-assessment', c.id, 'Module 3: Social Engineering — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Manipulating people psychologically into giving up confidential information or taking a harmful action"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"business","acceptableAnswers":["business email compromise","bec"]},{"id":"q4","type":"scenario","answer":"Refuse to share the password, and verify the caller\'s identity independently through a known official contact"},{"id":"q5","type":"matching","pairs":[{"left":"Phishing","right":"Fraudulent emails designed to trick you into revealing information or clicking a malicious link"},{"left":"Vishing","right":"Voice/phone-based social engineering scams"},{"left":"Business email compromise","right":"Impersonating an executive or vendor by email to trigger a fraudulent payment or data transfer"},{"left":"Malware","right":"Malicious software designed to damage, disrupt, or gain unauthorised access to a system"}]},{"id":"q6","type":"multiple-choice","answer":"Keeping software updated and avoiding downloads or attachments from untrusted sources"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Pause before clicking any links or attachments","Check the sender\'s actual address and look for other red flags","Verify the request independently through a separate, trusted channel if it seems unusual","Report the email through the correct channel rather than just deleting it"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-social-engineering';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-positive-psychology-fundamentals-assessment', c.id, 'Module 1: Positive Psychology Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Something significantly influenced by intentional habits and daily choices, not just fixed circumstances"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"distortion","acceptableAnswers":["distortions"]},{"id":"q4","type":"scenario","answer":"A cognitive distortion — an exaggerated, irrational leap from one data point to a sweeping negative conclusion"},{"id":"q5","type":"matching","pairs":[{"left":"Core beliefs","right":"Deep-seated assumptions about yourself and the world that shape your reactions"},{"left":"Cognitive distortion","right":"An exaggerated or irrational pattern of negative thinking"},{"left":"Purpose and meaning","right":"A sense that your actions and life connect to something that genuinely matters to you"},{"left":"Physical habits for well-being","right":"Routines like sleep, nutrition, and movement that support mental health"}]},{"id":"q6","type":"multiple-choice","answer":"Being intentional about screen time — for example, using apps for connection or gratitude rather than passive, endless scrolling"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Notice the automatic negative thought as it occurs","Identify the underlying core belief driving it","Examine the actual evidence for and against that belief","Reframe it into a more accurate, balanced belief"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-positive-psychology-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-forming-healthy-habits-assessment', c.id, 'Module 2: Forming Healthy Habits — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Repeating a small, consistent action, often anchored to an existing cue or routine"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"breathwork","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Anchor the new habit to an existing daily routine, like reading right after your morning coffee"},{"id":"q5","type":"matching","pairs":[{"left":"Habit cue","right":"The trigger that prompts an automatic behaviour"},{"left":"Morning routine","right":"A consistent sequence of habits that sets the tone for the day"},{"left":"Gratitude practice","right":"Regularly and deliberately noticing things you\'re thankful for"},{"left":"Breathwork","right":"Controlled breathing techniques used to reduce tension"}]},{"id":"q6","type":"multiple-choice","answer":"To wind down consistently, which supports better sleep and readiness for the next day"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Choose one small, specific habit to start with","Anchor it to an existing daily cue or routine","Repeat it consistently, even in a small or imperfect form","Track your consistency and adjust if it isn\'t sticking"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-forming-healthy-habits';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-positive-psychology-in-the-workplace-assessment', c.id, 'Module 3: Positive Psychology in the Workplace — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A combination of meaningful work, positive relationships, and a sense of autonomy or progress"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"perfectionism","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Workplace perfectionism undermining a genuine sense of accomplishment"},{"id":"q5","type":"matching","pairs":[{"left":"Flow","right":"A state of deep, absorbed engagement in a task"},{"left":"Meaning and purpose at work","right":"A sense that your work connects to something that genuinely matters to you"},{"left":"Healthy social life at work","right":"Building genuine, supportive relationships with colleagues"},{"left":"Workplace perfectionism","right":"Holding yourself to unrealistic standards that undermine well-being"}]},{"id":"q6","type":"multiple-choice","answer":"Taking regular short breaks and building in movement throughout the workday"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Choose a task that\'s challenging but within your actual ability","Remove likely distractions before starting","Set a clear, specific goal for the work session","Focus fully on the task, adjusting your approach based on feedback as you go"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-positive-psychology-in-the-workplace';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-exercise-assessment', c.id, 'Module 4: Exercise — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Frequency, Intensity, Time, and Type"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"desk","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Starting with short, manageable sessions that fit realistically into their existing schedule"},{"id":"q5","type":"matching","pairs":[{"left":"Frequency","right":"How often you exercise"},{"left":"Intensity","right":"How hard you\'re working during exercise"},{"left":"Time","right":"How long each session lasts"},{"left":"Type","right":"What kind of exercise you\'re doing"}]},{"id":"q6","type":"multiple-choice","answer":"Start at a manageable intensity and gradually increase as fitness improves"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Start with a short, realistic routine you can actually maintain","Schedule it consistently at the same time or trigger point","Gradually increase frequency, intensity, time, or type as it becomes easier","Track your consistency and adjust if motivation drops"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-exercise';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-mental-health-awareness-assessment', c.id, 'Module 5: Mental Health Awareness — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Foster open communication and check in genuinely, not just about output and deadlines"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"abuse","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Offer genuine, low-pressure support and flexibility, without forcing them to talk about it before they\'re ready"},{"id":"q5","type":"matching","pairs":[{"left":"Stigma","right":"Negative attitudes or misconceptions that discourage people from seeking mental health support"},{"left":"Substance abuse warning signs","right":"Behavioural changes like declining performance or unexplained absences"},{"left":"Manager\'s role in grief support","right":"Offering flexibility, resources, and genuine check-ins to a grieving employee"},{"left":"Supporting a co-worker with a mental health disorder","right":"Offering respectful, informed, non-judgmental support"}]},{"id":"q6","type":"multiple-choice","answer":"Treat them with the same respect and inclusion as any colleague, informed by accurate understanding rather than assumptions"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge the loss sincerely and without pressure","Offer specific, practical support rather than a vague \'let me know if you need anything\'","Respect their pace and preferences around returning to normal work","Check in again after the initial period, not just once"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-mental-health-awareness';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-dealing-with-emotions-assessment', c.id, 'Module 6: Dealing with Emotions — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Heightened stress and anxiety, since the brain treats unresolved uncertainty as a potential threat"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"rut","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Recognise this as the early build-up phase and use a technique to pause or de-escalate before it peaks"},{"id":"q5","type":"matching","pairs":[{"left":"Anger cycle build-up","right":"The early phase where tension rises before an outburst"},{"left":"Mental rut","right":"A prolonged period of feeling stuck or emotionally flat"},{"left":"Uncertainty response","right":"The brain treating unresolved unknowns as a potential threat"},{"left":"Finding a good therapist","right":"Identifying a qualified professional who is the right fit for your specific needs"}]},{"id":"q6","type":"multiple-choice","answer":"Name and acknowledge the emotion rather than suppressing or immediately acting on it"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Notice the early physical or mental signs of rising tension","Pause and create space before reacting","Use a calming technique, like breathing or stepping away briefly","Return to address the situation once you feel more level-headed"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-dealing-with-emotions';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-hr-fundamentals-assessment', c.id, 'Module 1: HR Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"fill-blank","answer":"Human Resources","acceptableAnswers":["human resources","HR"]},{"id":"q2","type":"multiple-choice","answer":"Identify the need, source and attract candidates, screen and interview, then select and make an offer"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Base pay","right":"Fixed, regular salary or wage for doing the job"},{"left":"Variable pay","right":"Performance-linked pay such as bonuses or commission"},{"left":"Benefits","right":"Non-cash offerings like healthcare or retirement contributions"},{"left":"Non-monetary compensation","right":"Rewards like recognition, flexibility, or growth opportunities that aren\'t paid in cash"}]},{"id":"q5","type":"scenario","answer":"Structured onboarding and training that helps them become productive and connected"},{"id":"q6","type":"multiple-choice","answer":"To address performance or conduct issues through a fair, escalating series of steps before more serious consequences"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Verbal warning and informal coaching","Written warning with documented expectations","Formal performance improvement plan or suspension","Termination if the issue remains unresolved"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-hr-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-diversity-inclusion-and-belonging-assessment', c.id, 'Module 2: Diversity, Inclusion and Belonging — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Diversity, Inclusion, and Belonging"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"matching","pairs":[{"left":"Diversity","right":"The presence of a wide range of different people and backgrounds"},{"left":"Inclusion","right":"Ensuring people genuinely feel able to participate and contribute"},{"left":"Belonging","right":"Feeling accepted and valued as your authentic self"},{"left":"Ally","right":"Someone who actively supports and advocates for underrepresented colleagues"}]},{"id":"q4","type":"fill-blank","answer":"belonging","acceptableAnswers":[]},{"id":"q5","type":"multiple-choice","answer":"Widening sourcing channels and using structured, bias-aware hiring criteria"},{"id":"q6","type":"ordering","items":["Broaden sourcing channels to reach a wider range of candidates","Use structured, consistent criteria to screen and interview fairly","Make an equitable offer and onboard thoughtfully","Track retention and belonging outcomes over time"]},{"id":"q7","type":"scenario","answer":"Address it respectfully in the moment or privately afterward, and support the affected colleague"},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-2-diversity-inclusion-and-belonging';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-interviewing-assessment', c.id, 'Module 3: Interviewing — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Reviewing the role requirements and the candidate\'s application, and planning consistent questions"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"behavioral","acceptableAnswers":["behavioural"]},{"id":"q4","type":"scenario","answer":"Continue the interview focused only on job-related questions and qualifications"},{"id":"q5","type":"matching","pairs":[{"left":"Structured interview","right":"Every candidate is asked the same core set of planned questions"},{"left":"Interviewer bias","right":"Unconscious preferences that unfairly skew evaluation of candidates"},{"left":"Illegal interview question","right":"A question that touches on a legally protected characteristic"},{"left":"Post-interview follow-up","right":"Timely communication with the candidate after the interview concludes"}]},{"id":"q6","type":"multiple-choice","answer":"Using structured, consistent questions and criteria scored the same way for every candidate"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Review the role requirements and candidate\'s application","Prepare structured, job-relevant questions in advance","Conduct the interview and take consistent notes","Follow up with the candidate afterward"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-interviewing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-unconscious-bias-assessment', c.id, 'Module 4: Unconscious Bias — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Automatic, unintentional mental associations that influence judgment without a person realising it"},{"id":"q2","type":"multiple-choice","answer":"Skewed hiring, evaluation, or promotion decisions that unfairly disadvantage some employees"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"fill-blank","answer":"affinity","acceptableAnswers":[]},{"id":"q5","type":"matching","pairs":[{"left":"Affinity bias","right":"Favouring people who remind you of yourself"},{"left":"Confirmation bias","right":"Favouring information that confirms what you already believe"},{"left":"Halo effect","right":"Letting one positive trait unfairly influence your whole impression of someone"},{"left":"Horns effect","right":"Letting one negative trait unfairly influence your whole impression of someone"},{"left":"Attribution bias","right":"Explaining others\' actions differently than you\'d explain your own"}]},{"id":"q6","type":"scenario","answer":"Affinity bias influencing the hiring decision"},{"id":"q7","type":"ordering","items":["Learn to recognise the common types of unconscious bias","Notice your own automatic reactions and assumptions in the moment","Slow down and question the reasoning behind a judgment","Use structured, consistent criteria to guide decisions"]},{"id":"q8","type":"true-false","answer":"True"}]' FROM `courses` c WHERE c.`slug` = 'module-4-unconscious-bias';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-talent-management-assessment', c.id, 'Module 5: Talent Management — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"It ensures the organisation can attract, grow, and keep the people it needs to meet its goals"},{"id":"q3","type":"fill-blank","answer":"strategy","acceptableAnswers":[]},{"id":"q4","type":"matching","pairs":[{"left":"Sourcing top talent","right":"Proactively identifying and attracting strong candidates"},{"left":"Developing talent","right":"Growing employees\' skills and capabilities over time"},{"left":"Retaining talent","right":"Keeping valued employees engaged and reducing turnover"},{"left":"Talent strategy","right":"The overall proactive plan tying these activities together"}]},{"id":"q5","type":"multiple-choice","answer":"Offering genuine growth opportunities and addressing engagement concerns proactively"},{"id":"q6","type":"scenario","answer":"Discuss a concrete development plan with new challenges or growth opportunities"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Assess current and future talent needs","Source and attract candidates who fit those needs","Develop employees\' skills once they\'re on board","Focus on retention to minimise unwanted turnover"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-talent-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-workplace-well-being-assessment', c.id, 'Module 6: Workplace Well-Being — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It\'s linked to improved engagement, productivity, and reduced absenteeism and turnover"},{"id":"q2","type":"fill-blank","answer":"assess","acceptableAnswers":["survey","gauge"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Low awareness of the program, and/or it not matching what employees actually want"},{"id":"q5","type":"multiple-choice","answer":"Communicating regularly and clearly about what\'s available and how to access it"},{"id":"q6","type":"matching","pairs":[{"left":"Business case for well-being","right":"Connecting employee health investment to real organisational outcomes"},{"left":"Assessing interests","right":"Finding out what employees actually want from a program"},{"left":"Diversifying programs","right":"Offering a range of options across different wellness needs"},{"left":"Boosting participation","right":"Actively encouraging employees to engage with what\'s offered"}]},{"id":"q7","type":"ordering","items":["Make the business case internally for investing in well-being","Assess what employees actually want and need","Design a diversified set of wellness offerings","Promote awareness and actively encourage participation"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-6-workplace-well-being';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-anti-harassment-and-discrimination-assessment', c.id, 'Module 7: Anti-Harassment and Discrimination — Test Your Knowledge', 80, '[{"id":"q1","type":"fill-blank","answer":"respectful","acceptableAnswers":[]},{"id":"q2","type":"multiple-choice","answer":"Protect employees from being treated unfairly based on legally protected characteristics"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Discrimination","right":"Unfair treatment based on a protected characteristic"},{"left":"Harassment","right":"Unwelcome conduct related to a protected characteristic that creates a hostile environment"},{"left":"Bystander intervention","right":"Safely stepping in or speaking up when witnessing harassment"},{"left":"Respectful workplace","right":"A culture where everyone is treated with dignity and fairness"}]},{"id":"q5","type":"scenario","answer":"Report it through the appropriate internal channel, such as HR or a supervisor"},{"id":"q6","type":"multiple-choice","answer":"Safely intervening in the moment, or supporting the affected colleague and reporting afterward"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Take the complaint seriously and listen without judgment","Follow the organisation\'s formal reporting and investigation process","Take appropriate corrective action based on the findings","Follow up to ensure the behaviour has stopped and there\'s no retaliation"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-anti-harassment-and-discrimination';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-retirement-planning-assessment', c.id, 'Module 8: Retirement Planning — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Starting early allows savings more time to grow, making long-term financial security more achievable"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"matching","pairs":[{"left":"Age milestones","right":"Key ages tied to retirement account rules, contributions, or withdrawals"},{"left":"Catching up","right":"Strategies for increasing savings when you\'re behind your goals"},{"left":"Retirement plan types","right":"The different structures, such as employer, personal, or pension plans, available for saving"},{"left":"Common mistakes","right":"Frequent errors that can seriously undermine retirement readiness"}]},{"id":"q4","type":"fill-blank","answer":"milestones","acceptableAnswers":[]},{"id":"q5","type":"multiple-choice","answer":"Increase contributions where possible and use available catch-up strategies"},{"id":"q6","type":"ordering","items":["Start contributing to a retirement plan as early as possible","Regularly review and adjust contributions as income grows","Reassess and catch up if you fall behind your goals","Plan withdrawals and income around key retirement age milestones"]},{"id":"q7","type":"scenario","answer":"Failing to periodically review and adjust retirement contributions over time"},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-8-retirement-planning';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-leadership-fundamentals-assessment', c.id, 'Module 1: Leadership Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"They inspire and influence others toward shared goals, rather than relying purely on positional power"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"vision","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Have a genuine one-on-one conversation to understand what\'s going on and reconnect their work to meaning"},{"id":"q5","type":"matching","pairs":[{"left":"Vision","right":"A clear picture of the future the team is working toward"},{"left":"Engagement","right":"Employees feeling connected to and invested in their work"},{"left":"Motivation","right":"The drive behind why people put in genuine effort"},{"left":"Modelling behaviour","right":"Leading by example so others follow the standard you set"}]},{"id":"q6","type":"multiple-choice","answer":"Regularly seeking feedback and adjusting your approach"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Clarify the vision clearly for yourself first","Communicate it in a way the team can genuinely connect with","Model behaviour that\'s consistent with the vision","Reinforce it regularly through feedback and recognition"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-leadership-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-leadership-styles-assessment', c.id, 'Module 2: Leadership Styles — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Autocratic"},{"id":"q2","type":"multiple-choice","answer":"Transactional"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"fill-blank","answer":"democratic","acceptableAnswers":[]},{"id":"q5","type":"matching","pairs":[{"left":"Autocratic","right":"Leader makes most decisions with minimal team input"},{"left":"Democratic","right":"Team members are actively consulted before decisions are made"},{"left":"Laissez-faire","right":"Team is given high autonomy and minimal direct oversight"},{"left":"Transactional","right":"Leader relies on clear rewards and consequences tied to performance"},{"left":"Transformational","right":"Leader inspires change by connecting work to a larger shared vision"}]},{"id":"q6","type":"scenario","answer":"Frustration and disengagement, since an overly autocratic approach doesn\'t fit a highly capable team"},{"id":"q7","type":"ordering","items":["Autocratic","Transactional","Democratic","Laissez-faire"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-2-leadership-styles';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-emotional-intelligence-assessment', c.id, 'Module 3: Emotional Intelligence — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Recognising your own emotions and how they affect your thoughts and behaviour"},{"id":"q3","type":"fill-blank","answer":"regulation","acceptableAnswers":[]},{"id":"q4","type":"matching","pairs":[{"left":"Self-awareness","right":"Recognising your own emotions and their impact"},{"left":"Self-regulation","right":"Managing your reactions and impulses, especially under pressure"},{"left":"Self-motivation","right":"Driving yourself forward using internal, not just external, reasons"},{"left":"Empathy","right":"Understanding and being attuned to what others are feeling"},{"left":"Social skills","right":"Building and managing relationships effectively"}]},{"id":"q5","type":"multiple-choice","answer":"Genuinely trying to understand a team member\'s perspective before responding"},{"id":"q6","type":"scenario","answer":"Pausing to manage the reaction before responding, rather than reacting on impulse"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Self-awareness","Self-regulation","Self-motivation","Empathy","Social skills"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-emotional-intelligence';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-crisis-management-assessment', c.id, 'Module 4: Crisis Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A significant, often unexpected event that threatens an organisation\'s operations, reputation, or stakeholders"},{"id":"q2","type":"fill-blank","answer":"preparation","acceptableAnswers":["preparedness","prevention and preparation","preparing"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Communicate honestly and promptly with affected stakeholders while working to contain and fix the issue"},{"id":"q5","type":"multiple-choice","answer":"Different crises (financial, reputational, operational, natural, personnel) require different response approaches"},{"id":"q6","type":"matching","pairs":[{"left":"Prevention and preparation","right":"Identifying risks and building a plan before a crisis hits"},{"left":"Response","right":"Acting quickly and communicating clearly while the crisis is unfolding"},{"left":"Recovery","right":"Rebuilding trust and operations, and reviewing lessons learned, after the crisis"},{"left":"Types of crises","right":"Recognising the different categories of threats an organisation can face"}]},{"id":"q7","type":"ordering","items":["Identify potential risks and build a preparedness plan","Detect and assess the crisis as it emerges","Respond quickly with clear action and communication","Recover, rebuild, and review lessons learned"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-4-crisis-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-marketing-fundamentals-assessment', c.id, 'Module 1: Marketing Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The activities involved in identifying, communicating, and delivering value to meet customer needs"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"mix","acceptableAnswers":["4 Ps","four Ps"]},{"id":"q4","type":"scenario","answer":"Develop a marketing plan that lays out goals, audience, budget, and strategy"},{"id":"q5","type":"matching","pairs":[{"left":"Unique Selling Proposition (USP)","right":"What makes a product or brand meaningfully different from competitors"},{"left":"Marketing funnel","right":"The stages a customer moves through from awareness to purchase"},{"left":"Persuasion","right":"Using honest, compelling reasoning to influence a decision"},{"left":"Manipulation","right":"Using deceptive or unfair tactics to influence a decision"}]},{"id":"q6","type":"multiple-choice","answer":"Persuasion relies on honest, transparent appeals, while manipulation uses deception or unfair pressure"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Awareness","Consideration","Conversion","Loyalty"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-marketing-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-brand-identity-and-strategy-assessment', c.id, 'Module 2: Brand Identity and Strategy — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The overall perception and feeling people associate with a company or product, not just its logo"},{"id":"q2","type":"multiple-choice","answer":"The set of human-like traits, such as playful, trustworthy, or bold, a brand consistently expresses"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"fill-blank","answer":"positioning","acceptableAnswers":[]},{"id":"q5","type":"matching","pairs":[{"left":"Brand personality","right":"The consistent human-like traits a brand expresses"},{"left":"Brand positioning","right":"Where a brand sits in customers\' minds relative to competitors"},{"left":"Brand story","right":"A compelling narrative that connects a brand to its audience"},{"left":"Rebranding","right":"Deliberately changing a brand\'s identity or strategy over time"}]},{"id":"q6","type":"scenario","answer":"A deliberate rebranding strategy to realign its identity with where it is today"},{"id":"q7","type":"ordering","items":["Define the brand\'s personality and core values","Establish clear positioning relative to competitors","Design consistent visual identity elements","Craft a compelling brand story to tie it together"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-2-brand-identity-and-strategy';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-product-marketing-assessment', c.id, 'Module 3: Product Marketing — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"The stages a product typically moves through, from introduction to growth, maturity, and decline"},{"id":"q3","type":"fill-blank","answer":"fit","acceptableAnswers":[]},{"id":"q4","type":"matching","pairs":[{"left":"Pricing strategy","right":"A deliberate approach to setting a product\'s price relative to value and market"},{"left":"Go-to-market strategy","right":"The overall plan for how a product will reach and be adopted by its market"},{"left":"Product launch","right":"The coordinated process of introducing a new product to the market"},{"left":"Product-market fit","right":"Evidence that a product genuinely satisfies real market demand"}]},{"id":"q5","type":"multiple-choice","answer":"Understanding the product\'s perceived value to customers alongside costs and competitor pricing"},{"id":"q6","type":"scenario","answer":"A complete go-to-market strategy covering all the functions needed for a successful launch"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Define the target audience and positioning","Finalise pricing and go-to-market strategy","Prepare marketing materials and product pages","Launch and actively monitor early customer response"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-product-marketing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-content-marketing-assessment', c.id, 'Module 4: Content Marketing — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Creating and sharing valuable, relevant content to attract and engage a target audience"},{"id":"q2","type":"fill-blank","answer":"voice","acceptableAnswers":[]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Content isn\'t being created with the target audience\'s needs and interests in mind"},{"id":"q5","type":"multiple-choice","answer":"Content should match where the customer is in the marketing funnel, from awareness to decision"},{"id":"q6","type":"matching","pairs":[{"left":"Content strategy","right":"The overall plan guiding what content is created and why"},{"left":"Distribution channels","right":"The platforms and places content is shared to reach an audience"},{"left":"Voice and tone","right":"The consistent personality and style behind a brand\'s communication"},{"left":"Business blogging","right":"Publishing articles on a company\'s own site to attract and inform an audience"}]},{"id":"q7","type":"ordering","items":["Define the target audience and their needs","Develop a content strategy and consistent voice","Create content suited to each stage of the funnel","Choose distribution channels and publish accordingly"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-4-content-marketing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-customer-and-marketing-research-assessment', c.id, 'Module 5: Customer and Marketing Research — Test Your Knowledge', 80, '[{"id":"q1","type":"fill-blank","answer":"persona","acceptableAnswers":[]},{"id":"q2","type":"multiple-choice","answer":"It provides real evidence about who customers are and what they need, rather than relying on assumptions"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"Target market","right":"The specific group of customers a business focuses on reaching"},{"left":"Buyer persona","right":"A research-based profile representing an ideal customer"},{"left":"Customer journey map","right":"A visual representation of the steps a customer takes toward a purchase"},{"left":"Competitive landscape analysis","right":"A structured look at competitors\' strengths, weaknesses, and positioning"},{"left":"Market segmentation","right":"Dividing a broad market into distinct, meaningful groups"}]},{"id":"q5","type":"scenario","answer":"A customer journey map"},{"id":"q6","type":"multiple-choice","answer":"Understand competitors\' strengths, weaknesses, and positioning to inform its own strategy"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Conduct customer research to gather real data","Identify and define the target market","Build buyer personas from that research","Map the customer journey and segment the market accordingly"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-customer-and-marketing-research';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-website-marketing-assessment', c.id, 'Module 6: Website Marketing — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Actively designing it to attract, engage, and convert visitors toward specific goals"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"matching","pairs":[{"left":"Landing page","right":"A focused page designed around a single conversion goal"},{"left":"Friction","right":"Anything that makes it harder or more confusing for a visitor to convert"},{"left":"Conversion","right":"A visitor completing a desired action, like a purchase or signup"},{"left":"Website as a marketing tool","right":"Actively designing a site to attract, engage, and convert visitors"}]},{"id":"q4","type":"fill-blank","answer":"friction","acceptableAnswers":[]},{"id":"q5","type":"multiple-choice","answer":"Simplifying navigation and shortening an unnecessarily long checkout or signup process"},{"id":"q6","type":"ordering","items":["Define a single, clear conversion goal","Craft a headline and message focused on that goal","Design the page to minimise distractions and friction","Include a clear, prominent call-to-action"]},{"id":"q7","type":"scenario","answer":"High friction, leading to more abandoned carts and fewer completed conversions"},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-6-website-marketing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-search-engine-optimization-assessment', c.id, 'Module 7: Search Engine Optimization — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The practice of improving a website so it ranks higher and attracts more relevant organic traffic from search engines"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"alt","acceptableAnswers":["alt text","alternative"]},{"id":"q4","type":"scenario","answer":"Technical SEO problems that are likely hurting its rankings regardless of content quality"},{"id":"q5","type":"matching","pairs":[{"left":"Keyword research","right":"Identifying the real terms people search for related to your content"},{"left":"Technical SEO","right":"Optimising a site\'s structure, speed, and functionality for search engines"},{"left":"Link-building","right":"Earning links from other sites that point back to your own"},{"left":"On-page content optimisation","right":"Structuring and writing content to align with SEO best practices"}]},{"id":"q6","type":"multiple-choice","answer":"Page load speed, content relevance, and quality backlinks, among other factors"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Research relevant keywords for the topic","Structure and optimise the content around those keywords","Address technical factors like site structure and speed","Build quality links pointing back to the page"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-search-engine-optimization';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-social-media-marketing-assessment', c.id, 'Module 8: Social Media Marketing — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Clear goals, target audience understanding, and platform fit, not simply posting activity"},{"id":"q2","type":"multiple-choice","answer":"Where the business\'s target audience actually spends time and how that fits the content"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"fill-blank","answer":"listening","acceptableAnswers":[]},{"id":"q5","type":"matching","pairs":[{"left":"Content buckets","right":"Recurring themes used to organise and balance planned content"},{"left":"Social listening","right":"Actively monitoring conversations and mentions relevant to your brand"},{"left":"Hashtags","right":"Searchable tags used to categorise and extend the reach of posts"},{"left":"Engagement","right":"Meaningful interaction, like likes, comments, or shares, from an audience"},{"left":"Social media metrics","right":"Measurable data points used to evaluate performance"}]},{"id":"q6","type":"scenario","answer":"One of the common reasons people disengage from brands: an overly repetitive, sales-heavy feed"},{"id":"q7","type":"ordering","items":["Define a social media strategy with clear goals","Choose the right channels for the target audience","Plan content using organised content buckets","Monitor metrics and engagement to refine the approach"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-8-social-media-marketing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-9-email-marketing-assessment', c.id, 'Module 9: Email Marketing — Test Your Knowledge', 80, '[{"id":"q1","type":"true-false","answer":"False"},{"id":"q2","type":"multiple-choice","answer":"Is honest, clear, and compelling enough to earn an open, without being misleading"},{"id":"q3","type":"fill-blank","answer":"A/B","acceptableAnswers":["a/b","ab"]},{"id":"q4","type":"matching","pairs":[{"left":"Segmentation","right":"Dividing an email list into groups based on shared characteristics"},{"left":"A/B testing","right":"Comparing two versions of an email to see which performs better"},{"left":"Email automation","right":"Emails triggered automatically based on a rule or customer action"},{"left":"Spam filter avoidance","right":"Practices that help legitimate emails reach the inbox instead of spam"}]},{"id":"q5","type":"multiple-choice","answer":"Using a reputable sending domain, honest subject lines, and permission-based lists"},{"id":"q6","type":"scenario","answer":"Setting up email automation so onboarding emails send automatically when someone signs up"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Segment the audience into relevant groups","Write a compelling subject line and email content","Apply core email design fundamentals for readability","Measure results and refine using A/B testing"]}]' FROM `courses` c WHERE c.`slug` = 'module-9-email-marketing';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-10-paid-advertising-assessment', c.id, 'Module 10: Paid Advertising — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Using paid advertising to increase visibility in search engine results"},{"id":"q2","type":"fill-blank","answer":"pay-per-click","acceptableAnswers":["PPC","pay per click"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Remarketing, targeting people who already showed interest but didn\'t convert"},{"id":"q5","type":"multiple-choice","answer":"Using clear, visually compelling design with a strong, easy-to-spot call-to-action"},{"id":"q6","type":"matching","pairs":[{"left":"SEM","right":"Using paid ads to gain visibility in search engine results"},{"left":"PPC","right":"An ad model where the advertiser pays per click received"},{"left":"Display advertising","right":"Visual ads shown across websites and apps in a broader ad network"},{"left":"Out-of-home advertising","right":"Physical ads encountered in public spaces, like billboards or transit"},{"left":"Remarketing","right":"Targeting ads at people who already engaged but didn\'t convert"}]},{"id":"q7","type":"ordering","items":["Define the campaign\'s goal and target audience","Choose the right paid channel, such as search, display, or out-of-home","Design compelling ad creative with a clear call-to-action","Monitor performance and use remarketing to recapture interested visitors"]},{"id":"q8","type":"true-false","answer":"False"}]' FROM `courses` c WHERE c.`slug` = 'module-10-paid-advertising';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-11-marketing-analytics-assessment', c.id, 'Module 11: Marketing Analytics — Test Your Knowledge', 80, '[{"id":"q1","type":"fill-blank","answer":"KPI","acceptableAnswers":[]},{"id":"q2","type":"multiple-choice","answer":"The practice of collecting and analysing data to evaluate and improve marketing performance"},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"matching","pairs":[{"left":"KPI","right":"A specific measurable value tied to a marketing goal"},{"left":"Campaign effectiveness measurement","right":"Evaluating whether a campaign actually achieved its intended results"},{"left":"Data interpretation","right":"Making sense of what collected data actually means"},{"left":"Data storytelling","right":"Communicating data findings in a clear, compelling narrative"}]},{"id":"q5","type":"scenario","answer":"Using data storytelling to present the findings as a clear, compelling narrative"},{"id":"q6","type":"multiple-choice","answer":"Looking for patterns and context rather than reacting to a single data point in isolation"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Choose KPIs that match the campaign\'s actual goals","Collect relevant campaign data over time","Interpret the data for real patterns and context","Communicate the findings clearly through data storytelling"]}]' FROM `courses` c WHERE c.`slug` = 'module-11-marketing-analytics';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-inclusion-and-respect-assessment', c.id, 'Module 1: Inclusion and Respect — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A shared belief that team members can speak up, take risks, or admit mistakes without fear of punishment or humiliation"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"spectrum","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Gender bias — an assumption made about someone\'s preferences or capability based on gender rather than asking them directly"},{"id":"q5","type":"matching","pairs":[{"left":"Psychological safety","right":"Feeling safe to speak up, question, or admit mistakes without fear of punishment"},{"left":"Gender bias","right":"Treating someone differently based on assumptions tied to their gender"},{"left":"Inclusive remote environment","right":"Deliberately ensuring remote team members are equally seen, heard, and included"},{"left":"Gender spectrum","right":"The full range of gender identities beyond a strict binary"}]},{"id":"q6","type":"multiple-choice","answer":"Rotating meeting times and actively inviting quieter voices to contribute on calls"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Notice the assumption being made and name it to yourself","Ask a clarifying question that surfaces the assumption to the group","Suggest checking directly with the person affected","Follow up to ensure the decision reflects their actual input"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-inclusion-and-respect';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-inclusive-communication-assessment', c.id, 'Module 2: Inclusive Communication — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Acknowledge the impact of what you said, apologise sincerely, and adjust — regardless of your intent"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"shared","acceptableAnswers":["shared agreements"]},{"id":"q4","type":"scenario","answer":"Calmly and directly name that the comment wasn\'t okay, without escalating into a personal attack"},{"id":"q5","type":"matching","pairs":[{"left":"Impact vs. intent","right":"Recognising that how words land can differ from what the speaker meant"},{"left":"Employee voice","right":"Ensuring people\'s input and concerns are genuinely heard and valued"},{"left":"Shared agreements","right":"A team\'s explicit, co-created norms for respectful communication"},{"left":"Accessible writing","right":"Writing clearly and formatting content so it\'s usable by the widest range of readers"}]},{"id":"q6","type":"multiple-choice","answer":"Removing unnecessary friction or harm from everyday language without losing your meaning"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Listen fully before forming your response","Ask a clarifying question instead of assuming their meaning","Acknowledge their perspective, even if you disagree","Share your own view without dismissing theirs"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-inclusive-communication';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-culture-competence-assessment', c.id, 'Module 3: Culture Competence — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The ability to understand, communicate with, and effectively interact with people across different cultures"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"appropriation","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Consider the request fairly and try to accommodate it, the same way you would for any other legitimate personal need"},{"id":"q5","type":"matching","pairs":[{"left":"Cultural sensitivity","right":"Being aware of and respectful toward cultural differences in everyday interactions"},{"left":"Managing multicultural teams","right":"Adapting leadership and communication style to a team\'s varied cultural backgrounds"},{"left":"Cultural appropriation","right":"Using another culture\'s meaningful practices or symbols without understanding or respect"},{"left":"Presenting across cultures","right":"Adapting communication style, pace, and examples for an international audience"}]},{"id":"q6","type":"multiple-choice","answer":"Exercising discretion, respecting differing views, and keeping such conversations appropriate for a professional setting"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Learn about the cultural backgrounds and communication norms represented on your team","Adapt your communication style and expectations accordingly","Check in individually to confirm understanding, rather than assuming it","Adjust your approach based on what you learn from those check-ins"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-culture-competence';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-problem-solving-fundamentals-assessment', c.id, 'Module 1: Problem Solving Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A complicated problem has many parts but a knowable solution; a complex problem involves unpredictable interactions with no single fixed solution"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"grow","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"A complex problem, since the variables are interacting unpredictably rather than following a fixed, knowable pattern"},{"id":"q5","type":"matching","pairs":[{"left":"Complicated problem","right":"Many parts, but a knowable, analysable solution"},{"left":"Complex problem","right":"Unpredictable interactions with no single fixed solution"},{"left":"Barrier to problem-solving","right":"An obstacle, like fear of failure, that prevents effective problem-solving"},{"left":"Growing problem-solving skills","right":"Deliberately building the ability through practice and feedback"}]},{"id":"q6","type":"multiple-choice","answer":"Clearly defining the actual problem before jumping to solutions"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Notice what\'s actually preventing progress on the problem","Identify whether the barrier is practical, psychological, or informational","Choose a strategy suited to that specific type of barrier","Apply it and reassess whether progress has resumed"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-problem-solving-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-problem-solving-in-the-workplace-assessment', c.id, 'Module 2: Problem Solving in the Workplace — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Involving the right people, gathering relevant input, and making a well-reasoned decision rather than acting alone on instinct"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"prioritizing","acceptableAnswers":["prioritising","prioritization","prioritisation"]},{"id":"q4","type":"scenario","answer":"The client complaint, since it\'s both urgent and has significant potential impact"},{"id":"q5","type":"matching","pairs":[{"left":"Effective leadership problem-solving","right":"Involving the right people and reasoning through a decision"},{"left":"Creative problem-solving culture","right":"An environment where reasonable risk-taking and new ideas are supported, not punished"},{"left":"Team problem-solving","right":"Combining diverse perspectives and skills to solve a shared problem"},{"left":"Prioritizing workplace problems","right":"Ranking problems by urgency and impact before deciding what to tackle first"}]},{"id":"q6","type":"multiple-choice","answer":"Actively drawing out and combining diverse perspectives and skills from team members"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Model curiosity and openness to new ideas as a leader","Create psychological safety around reasonable risk-taking","Actively invite and welcome diverse input on problems","Recognise and reinforce good-faith attempts, even when they don\'t fully succeed"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-problem-solving-in-the-workplace';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-steps-to-problem-solving-assessment', c.id, 'Module 3: Steps to Problem Solving — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Finding the underlying source driving the problem, not just its visible symptoms"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"evaluating","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Evaluating the results after implementation, to confirm the solution actually worked"},{"id":"q5","type":"matching","pairs":[{"left":"Defining the problem","right":"Clearly identifying the actual problem and its root cause"},{"left":"Brainstorming","right":"Freely generating a wide range of possible solutions before judging them"},{"left":"Evaluating solutions","right":"Comparing options against criteria like cost, feasibility, and impact"},{"left":"Evaluating results","right":"Checking after implementation whether the solution actually worked"}]},{"id":"q6","type":"multiple-choice","answer":"Planning the rollout, communicating clearly, and monitoring progress as it\'s put into action"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Define the problem and identify its root cause","Brainstorm a range of possible solutions","Research and evaluate those solutions against real criteria","Implement the best solution and evaluate the results"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-steps-to-problem-solving';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-advanced-problem-solving-assessment', c.id, 'Module 4: Advanced Problem-Solving — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Generating a wide range of different possible ideas or solutions"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"reframing","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Reframing the problem to open up a new, more productive set of possible solutions"},{"id":"q5","type":"matching","pairs":[{"left":"Divergent thinking","right":"Generating a wide range of different possible ideas"},{"left":"Convergent thinking","right":"Narrowing many options down to the single best solution"},{"left":"Heuristic","right":"A mental shortcut that speeds up decisions but can introduce errors"},{"left":"Reframing","right":"Changing how a problem is defined to reveal new possible solutions"}]},{"id":"q6","type":"multiple-choice","answer":"An iterative, human-centred approach that cycles through empathy, ideation, and prototyping rather than moving in one straight line"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Reframe the problem to open up new possible angles","Use divergent thinking to generate a wide range of possible ideas","Apply convergent thinking to narrow those ideas down to the strongest options","Test and refine the leading option before fully committing"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-advanced-problem-solving';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-project-management-fundamentals-assessment', c.id, 'Module 1: Project Management Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Applying knowledge, skills, and processes to achieve specific project objectives within constraints like time and cost"},{"id":"q2","type":"fill-blank","answer":"closure","acceptableAnswers":["closing","close-out","closeout"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"A proper closure phase"},{"id":"q5","type":"matching","pairs":[{"left":"Initiation","right":"Defining the project\'s purpose and securing approval to proceed"},{"left":"Planning","right":"Creating the project plan, schedule, and budget"},{"left":"Execution","right":"The team carries out the work to produce the agreed deliverables"},{"left":"Closure","right":"Formally ending the project and capturing lessons learned"}]},{"id":"q6","type":"multiple-choice","answer":"Clear roles and responsibilities combined with regular communication"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Initiation","Planning","Execution","Closure"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-project-management-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-project-frameworks-assessment', c.id, 'Module 2: Project Frameworks — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A structured approach and set of processes that guides how a project is planned and executed"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"work in progress","acceptableAnswers":["wip","work-in-progress"]},{"id":"q4","type":"scenario","answer":"An agile-style framework such as Scrum, built around iteration and change"},{"id":"q5","type":"matching","pairs":[{"left":"Critical path method","right":"Identifies the longest sequence of dependent tasks that determines the minimum project duration"},{"left":"Critical chain method","right":"Adds buffers to the schedule to explicitly account for resource constraints"},{"left":"Kanban","right":"Visualises continuous flow of work on a board, with limits on work in progress"},{"left":"Scrum","right":"Organises work into time-boxed sprints with defined roles and ceremonies"}]},{"id":"q6","type":"multiple-choice","answer":"Critical chain explicitly accounts for resource availability, not just task dependencies"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Assess how likely the project\'s requirements are to change","Consider the team\'s size, structure, and experience","Evaluate stakeholder expectations for visibility and reporting","Select and pilot the framework on the project"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-project-frameworks';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-project-communication-assessment', c.id, 'Module 3: Project Communication — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It keeps stakeholders aligned, surfaces risks early, and prevents misunderstandings"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"communication","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"A direct conversation or call, rather than a routine email update"},{"id":"q5","type":"matching","pairs":[{"left":"Email","right":"Non-urgent, documented updates"},{"left":"Status meeting","right":"Synchronous alignment and questions"},{"left":"One-on-one conversation","right":"Sensitive or nuanced issues"},{"left":"Project dashboard","right":"Real-time visibility for stakeholders between updates"}]},{"id":"q6","type":"multiple-choice","answer":"A clear agenda circulated in advance"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Identify stakeholders and their information needs","Decide the appropriate channel and frequency for each stakeholder","Document and share the plan","Review and adjust the plan as the project evolves"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-project-communication';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-project-scheduling-assessment', c.id, 'Module 4: Project Scheduling — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A timeline showing when project activities and tasks will be performed and completed"},{"id":"q2","type":"fill-blank","answer":"start-to-finish","acceptableAnswers":[]},{"id":"q3","type":"true-false","answer":"True"},{"id":"q4","type":"scenario","answer":"Use historical data and techniques like three-point estimating instead of optimistic guessing"},{"id":"q5","type":"matching","pairs":[{"left":"Finish-to-start","right":"Task B can\'t start until Task A finishes"},{"left":"Start-to-start","right":"Task B can\'t start until Task A starts"},{"left":"Finish-to-finish","right":"Task B can\'t finish until Task A finishes"},{"left":"Start-to-finish","right":"Task B can\'t finish until Task A starts"}]},{"id":"q6","type":"multiple-choice","answer":"The people, equipment, and materials needed, and when they\'re needed"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Define deliverables and break them into activities","Estimate the time needed for each activity","Sequence activities based on their dependencies","Assign resources and finalise the schedule"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-project-scheduling';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-project-scope-management-assessment', c.id, 'Module 5: Project Scope Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The process of defining and controlling what is and isn\'t included in a project"},{"id":"q2","type":"fill-blank","answer":"creep","acceptableAnswers":[]},{"id":"q3","type":"true-false","answer":"True"},{"id":"q4","type":"scenario","answer":"Evaluate the request through a formal change control process before agreeing to it"},{"id":"q5","type":"matching","pairs":[{"left":"Requirements","right":"The specific needs and conditions the project must satisfy"},{"left":"Scope statement","right":"A document that defines what is and isn\'t included in the project"},{"left":"Work Breakdown Structure","right":"A hierarchical breakdown of the total scope into deliverables and tasks"},{"left":"Scope creep","right":"Unmanaged, unapproved expansion of the project\'s scope over time"}]},{"id":"q6","type":"multiple-choice","answer":"Route any proposed scope change through a formal change control process"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Gather requirements from stakeholders","Define and document the project scope statement","Break the scope into a Work Breakdown Structure","Control any proposed changes through a formal change process"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-project-scope-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-project-reporting-assessment', c.id, 'Module 6: Project Reporting — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"To give stakeholders accurate, timely visibility into progress, risks, and budget"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"key performance indicators","acceptableAnswers":["key performance indicator"]},{"id":"q4","type":"scenario","answer":"Log the risk in a risk register, assess its impact and likelihood, and report it transparently"},{"id":"q5","type":"matching","pairs":[{"left":"Status report","right":"A regular update on progress, budget, and risks"},{"left":"Risk register","right":"A log of identified risks, their likelihood and impact, and mitigation plans"},{"left":"Budget tracking","right":"Comparing actual project spend against the planned budget"},{"left":"KPI","right":"A measurable indicator used to judge project performance"}]},{"id":"q6","type":"multiple-choice","answer":"A root cause analysis (fishbone) diagram"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Establish the project budget baseline","Track actual spend against the baseline regularly","Report cost variances to stakeholders","Take corrective action when costs drift off track"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-project-reporting';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-project-improvement-assessment', c.id, 'Module 7: Project Improvement — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Failing to define clear roles and responsibilities early in the project"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"post-implementation","acceptableAnswers":["post implementation"]},{"id":"q4","type":"scenario","answer":"Conduct post-implementation reviews and apply the lessons learned to future projects"},{"id":"q5","type":"matching","pairs":[{"left":"Unclear scope","right":"Leads to scope creep and stakeholder disagreement"},{"left":"Poor communication","right":"Stakeholders are surprised by issues too late"},{"left":"Unrealistic scheduling","right":"Team burnout and missed deadlines"},{"left":"Ignoring risk management","right":"Preventable issues derail the project"}]},{"id":"q6","type":"multiple-choice","answer":"To capture what went well and what didn\'t, in order to improve future projects"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Gather feedback from the team and the client","Compare actual outcomes against the planned objectives","Identify the root causes of what went well or poorly","Document lessons learned and share them for future projects"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-project-improvement';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-project-change-management-assessment', c.id, 'Module 8: Project Change Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A formal way to evaluate, approve, and control proposed changes to scope, schedule, or budget"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"budget","acceptableAnswers":["cost","costs"]},{"id":"q4","type":"scenario","answer":"Build genuine buy-in by communicating the rationale and benefits, and involving the stakeholder in the rollout"},{"id":"q5","type":"matching","pairs":[{"left":"Change request","right":"A formal proposal to modify project scope, schedule, or budget"},{"left":"Impact analysis","right":"Assessing how a proposed change affects the project\'s constraints"},{"left":"Sponsorship and buy-in","right":"Securing genuine support from stakeholders for the change"},{"left":"Change implementation","right":"Rolling out an approved change in a controlled way"}]},{"id":"q6","type":"multiple-choice","answer":"Without it, people may resist or undermine the change even after it\'s formally approved"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Submit and document the change request","Analyse the change\'s impact on scope, schedule, and budget","Secure approval and stakeholder buy-in","Implement the change and update project documentation"]}]' FROM `courses` c WHERE c.`slug` = 'module-8-project-change-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-resilience-fundamentals-assessment', c.id, 'Module 1: Resilience Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The capacity to adapt well and recover quickly from setbacks, stress, or change at work"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"pillars","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Acknowledge the setback honestly, involve the team in adapting the plan, and offer real support"},{"id":"q5","type":"matching","pairs":[{"left":"Self-awareness","right":"Recognising your own emotional reactions and stress triggers"},{"left":"Self-care","right":"Maintaining habits that protect your physical and mental energy"},{"left":"Positive relationships","right":"Having a support network you can rely on during hard times"},{"left":"Purpose","right":"Having a clear sense of meaning that keeps you motivated through setbacks"},{"left":"Mindset","right":"Approaching challenges with a growth-oriented, adaptable outlook"}]},{"id":"q6","type":"multiple-choice","answer":"Open communication where people feel safe raising concerns and problems early"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge the setback openly with the team","Involve the team in identifying a path forward","Provide the support and resources needed to adapt","Recognise and reinforce adaptive behaviour going forward"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-resilience-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-building-career-resilience-assessment', c.id, 'Module 2: Building Career Resilience — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Actively seeking out new knowledge and feedback, and applying it"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"lifelong","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Proactively seek out new training, ask for stretch assignments, and build relevant relationships"},{"id":"q5","type":"matching","pairs":[{"left":"Lifelong learning","right":"Continuously seeking new skills and knowledge throughout your career"},{"left":"Professional relationships","right":"A network of colleagues and mentors that supports your growth"},{"left":"Ownership of your career","right":"Proactively steering your own development rather than waiting to be told"},{"left":"Networking","right":"Deliberately building relationships beyond your immediate role or team"}]},{"id":"q6","type":"multiple-choice","answer":"They provide support, opportunities, and different perspectives when navigating career challenges"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Reflect on your goals and identify current gaps","Seek out learning and feedback opportunities proactively","Build relationships that support your growth","Regularly reassess and adjust your career plan"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-building-career-resilience';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-leadership-and-resilience-assessment', c.id, 'Module 3: Leadership and Resilience — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Reflecting on setbacks constructively and modelling a steady, adaptive response for the team"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"modeling","acceptableAnswers":["modelling"]},{"id":"q4","type":"scenario","answer":"Communicate honestly about the situation, refocus priorities with the team, and support them through it"},{"id":"q5","type":"matching","pairs":[{"left":"Modelling calm, adaptive behaviour","right":"Shows the team how to respond under pressure"},{"left":"Communicating honestly during a crisis","right":"Maintains trust even when the news is difficult"},{"left":"Involving the team in solutions","right":"Builds shared ownership of the recovery"},{"left":"Recognising effort and progress","right":"Sustains morale through a prolonged challenge"}]},{"id":"q6","type":"multiple-choice","answer":"A resilient team can adapt and keep performing through setbacks without the leader managing every crisis personally"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Assess the situation honestly and gather the facts","Communicate clearly and calmly with the team","Involve the team in shaping the response","Follow through and recognise the team\'s efforts"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-leadership-and-resilience';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-emotional-and-physical-resilience-assessment', c.id, 'Module 4: Emotional and Physical Resilience — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"It helps you recognise your emotional triggers and reactions so you can respond deliberately"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"agility","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Pause and process the feedback objectively before responding"},{"id":"q5","type":"matching","pairs":[{"left":"Self-awareness","right":"Recognising your own emotional patterns and triggers"},{"left":"Mental agility","right":"Adapting your thinking quickly to new or changing situations"},{"left":"Emotional self-regulation","right":"Managing your emotional reactions constructively"},{"left":"Healthy optimism","right":"A realistic, constructive outlook that still acknowledges real difficulties"},{"left":"Physical resilience","right":"Habits like sleep, exercise, and nutrition that sustain your capacity to cope"}]},{"id":"q6","type":"multiple-choice","answer":"A realistic, grounded outlook that things can improve, without ignoring real risks"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Notice and name what you\'re feeling","Pause before reacting","Reframe the situation realistically","Support your capacity to cope with sleep, movement, and nutrition"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-emotional-and-physical-resilience';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-thriving-through-challenges-assessment', c.id, 'Module 5: Thriving Through Challenges — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Break it into manageable steps and focus on what\'s within your control"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"comfort zone","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Address it directly and calmly, focusing on the issue rather than the person, to find a workable outcome"},{"id":"q5","type":"matching","pairs":[{"left":"Comfort zone","right":"The familiar space where you feel capable and face low risk"},{"left":"Rest and recovery","right":"Deliberately recharging to sustain long-term performance"},{"left":"Reframing a challenge as an opportunity","right":"Looking for what can be learned or gained from a setback"},{"left":"Constructive response to criticism","right":"Using feedback to identify a genuine area to improve"}]},{"id":"q6","type":"multiple-choice","answer":"As information that can highlight a genuine area for growth, once you\'ve processed the initial reaction"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge the difficulty of the situation honestly","Identify what is actually within your control","Look for what the situation could teach you or open up","Take one concrete adaptive action forward"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-thriving-through-challenges';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-sales-fundamentals-assessment', c.id, 'Module 1: Sales Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Consultative, relationship-focused selling that helps buyers solve real problems"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"Relationship","acceptableAnswers":["relationships"]},{"id":"q4","type":"scenario","answer":"Send relevant, educational content that addresses their likely problem, rather than a hard sales pitch"},{"id":"q5","type":"matching","pairs":[{"left":"CRM system","right":"Software that tracks and manages every interaction with leads and customers"},{"left":"Sales pipeline","right":"A visual view of where each prospect sits in the buying process"},{"left":"Essential sales tools","right":"The software and resources (CRM, email, scheduling) that support the sales process"},{"left":"Sales-marketing alignment","right":"Sales and marketing teams working from shared goals and definitions"}]},{"id":"q6","type":"multiple-choice","answer":"It builds the trust that long-term customer relationships depend on"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Awareness — the buyer recognises they have a problem","Consideration — the buyer researches possible solutions","Decision — the buyer selects and commits to a solution"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-sales-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-sales-leadership-and-management-assessment', c.id, 'Module 2: Sales Leadership and Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Moving from personally closing deals to enabling the whole team to close deals"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"battle card","acceptableAnswers":["battle cards","battlecard"]},{"id":"q4","type":"scenario","answer":"The quota is likely unrealistic and could demoralise the team and hurt retention"},{"id":"q5","type":"matching","pairs":[{"left":"SPIN Selling","right":"Guides the conversation through Situation, Problem, Implication and Need-payoff questions"},{"left":"Challenger Sale","right":"The rep teaches the buyer something new, tailors the message, and takes control of the conversation"},{"left":"Consultative Selling","right":"The rep acts as an advisor, diagnosing needs before proposing a solution"},{"left":"Solution Selling","right":"The rep focuses the pitch on solving a specific, identified customer problem"}]},{"id":"q6","type":"multiple-choice","answer":"To predict future revenue based on pipeline data, guiding business decisions"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Map out the buyer\'s journey and define clear pipeline stages","Document the process so the whole team follows it consistently","Roll out and train the team on the new process","Track performance data and refine the process over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-sales-leadership-and-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-sales-psychology-assessment', c.id, 'Module 3: Sales Psychology — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Largely emotional, problem-driven decisions that are then justified with logic"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"body language","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Treat it as useful feedback, learn from it professionally, and move on to the next opportunity"},{"id":"q5","type":"matching","pairs":[{"left":"Dominant / results-driven type","right":"Get straight to the point and focus on outcomes"},{"left":"Influential / outgoing type","right":"Build rapport and bring energy and enthusiasm"},{"left":"Steady / relationship-focused type","right":"Reassure them and avoid high-pressure tactics"},{"left":"Analytical / detail-focused type","right":"Provide thorough data and detailed information"}]},{"id":"q6","type":"multiple-choice","answer":"Build in recovery routines and realistic boundaries around work"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge the disappointment briefly without dwelling on it","Ask for feedback on the decision, if appropriate","Reflect on what could be improved next time","Move on to the next prospecting opportunity"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-sales-psychology';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-presenting-your-solution-assessment', c.id, 'Module 4: Presenting your Solution — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A feature is what the product does; a benefit is what that actually means for the buyer"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"features","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Adjust the emphasis for each audience — ROI and cost for the CFO, usability and daily impact for the frontline team"},{"id":"q5","type":"matching","pairs":[{"left":"Sales narrative","right":"A structured story connecting the buyer\'s problem to your solution"},{"left":"Slide deck","right":"Visual support that reinforces the spoken pitch, not a replacement for it"},{"left":"Product demonstration","right":"A hands-on show of the solution solving the buyer\'s specific problem"},{"left":"Proposal","right":"A formal written document outlining scope, solution, and pricing"}]},{"id":"q6","type":"multiple-choice","answer":"Creating false urgency about a deadline that doesn\'t actually exist"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Research the prospect and their likely needs","Define clear objectives for what the presentation should achieve","Tailor the content and messaging to this specific audience","Rehearse the delivery and prepare for likely questions or objections"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-presenting-your-solution';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-building-relationships-assessment', c.id, 'Module 5: Building Relationships — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Acting as an advisor who diagnoses the buyer\'s real needs before recommending a solution"},{"id":"q2","type":"fill-blank","answer":"Timeline","acceptableAnswers":["timing"]},{"id":"q3","type":"true-false","answer":"False"},{"id":"q4","type":"scenario","answer":"Ask a follow-up question to genuinely understand that frustration before proposing anything"},{"id":"q5","type":"matching","pairs":[{"left":"Decision-maker","right":"Has the final authority to approve the purchase"},{"left":"Influencer","right":"Shapes the decision without having final approval authority"},{"left":"Gatekeeper","right":"Controls or filters access to the decision-maker"},{"left":"End user","right":"Will actually use the solution day-to-day once purchased"}]},{"id":"q6","type":"multiple-choice","answer":"It helps reps read and respond appropriately to a buyer\'s emotions and concerns, building trust"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Listen actively to understand their real situation","Follow through consistently on small commitments","Be transparent about what your solution can and can\'t do","Deliver genuine value before asking for the sale"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-building-relationships';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-closing-the-deal-assessment', c.id, 'Module 6: Closing the Deal — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"A mutually beneficial agreement that preserves the relationship"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"conditional","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Stay calm, avoid being pressured into an immediate cave, and re-anchor the conversation around value"},{"id":"q5","type":"matching","pairs":[{"left":"Good cop / bad cop","right":"One buyer plays friendly while another pushes hard for concessions"},{"left":"The flinch","right":"Reacting with visible shock to an offer to pressure a better price"},{"left":"Take-it-or-leave-it","right":"Presenting an ultimatum to force a quick concession"},{"left":"Strategic silence","right":"Pausing after an offer to pressure the seller into filling the gap"}]},{"id":"q6","type":"multiple-choice","answer":"They start asking detailed questions about implementation and logistics"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Reconfirm the buyer\'s key requirements and value drivers","Negotiate terms using conditional concessions","Close the sale and confirm the agreement in writing","Transition the account to customer success"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-closing-the-deal';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-handling-objections-assessment', c.id, 'Module 7: Handling Objections — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Acknowledge it and ask a clarifying question to understand the real concern"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"value","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Ask a genuine, specific question to understand what exactly they need to think through"},{"id":"q5","type":"matching","pairs":[{"left":"\\"It\'s too expensive\\"","right":"Perceived value doesn\'t yet match the price"},{"left":"\\"I need to check with my team\\"","right":"Concern about buying authority or internal consensus"},{"left":"\\"We\'re happy with our current provider\\"","right":"Perceived risk or effort involved in switching"},{"left":"\\"Just send me some information\\"","right":"A need for more proof, or a polite way to end the conversation for now"}]},{"id":"q6","type":"multiple-choice","answer":"Getting defensive or arguing with the prospect"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Listen fully without interrupting","Acknowledge and validate the concern","Ask a clarifying question to find the real issue","Respond directly and confirm the concern is resolved"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-handling-objections';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-prospecting-assessment', c.id, 'Module 8: Prospecting — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The process of identifying and researching potential customers before reaching out"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"warm","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Share relevant insights and build a genuine professional connection before pitching anything"},{"id":"q5","type":"matching","pairs":[{"left":"Cold calling","right":"Reaching out to a prospect with no prior interaction"},{"left":"Warm calling","right":"Reaching out to a prospect who has already shown some engagement"},{"left":"Social selling","right":"Building relationships and credibility with prospects through social platforms"},{"left":"Competitive analysis","right":"Researching competitors to understand how to position your solution"}]},{"id":"q6","type":"multiple-choice","answer":"It helps you understand how to position your solution\'s unique value against alternatives"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Research the prospect briefly beforehand","Open with a clear, relevant reason for the call","Ask a genuine discovery question","Set a concrete next step or follow-up"]}]' FROM `courses` c WHERE c.`slug` = 'module-8-prospecting';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-stress-fundamentals-assessment', c.id, 'Module 1: Stress Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The body\'s physical and mental response to a demand or challenge"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"flight","acceptableAnswers":["flight response"]},{"id":"q4","type":"scenario","answer":"A personal stress trigger — a specific, identifiable situation that reliably provokes your stress response"},{"id":"q5","type":"matching","pairs":[{"left":"Stress","right":"The body\'s physical and mental response to a demand or challenge"},{"left":"Fight-or-flight response","right":"The body\'s automatic physiological reaction to a perceived threat"},{"left":"Stress trigger","right":"A specific, identifiable situation that reliably provokes a stress response"},{"left":"Good stress","right":"Short-term stress that can motivate and sharpen focus"}]},{"id":"q6","type":"multiple-choice","answer":"It is prolonged, feels overwhelming, and impairs rather than improves performance"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Notice a recurring physical or emotional stress reaction","Trace it back to identify the specific situation or trigger","Reflect on why that particular trigger affects you","Choose a strategy to manage your response the next time it occurs"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-stress-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-stress-and-work-performance-assessment', c.id, 'Module 2: Stress and Work Performance — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"An inverted U-shape — performance improves with pressure up to a point, then declines if pressure becomes excessive"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"burnout","acceptableAnswers":[]},{"id":"q4","type":"scenario","answer":"Use a focused technique (like controlled breathing or a brief mental reset) to calm your physical response before continuing your preparation"},{"id":"q5","type":"matching","pairs":[{"left":"Pressure-performance relationship","right":"Performance rises with pressure up to a point, then declines if pressure becomes excessive"},{"left":"Mental focus under stress","right":"Techniques used to stay clear-headed despite stress"},{"left":"Burnout","right":"Chronic physical and emotional exhaustion from prolonged unmanaged stress"},{"left":"Burnout recovery","right":"The deliberate process of restoring your energy and well-being after burnout"}]},{"id":"q6","type":"multiple-choice","answer":"A growing sense of cynicism or detachment from work that doesn\'t go away after a weekend off"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Recognise and acknowledge the signs of burnout rather than pushing through","Create space for genuine rest and recovery","Identify and address the root causes contributing to it","Rebuild sustainable habits and boundaries going forward"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-stress-and-work-performance';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-strategies-to-relieve-stress-assessment', c.id, 'Module 3: Strategies to Relieve Stress — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Going for a walk or journaling about what\'s bothering you"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"locus","acceptableAnswers":["locus of control"]},{"id":"q4","type":"scenario","answer":"A quick sensory-based technique, like focused breathing or grounding through your senses"},{"id":"q5","type":"matching","pairs":[{"left":"Meditation","right":"A practice of focused attention used to calm the mind over time"},{"left":"Journaling","right":"Writing to process and reflect on your thoughts and feelings"},{"left":"Cognitive reframing","right":"Deliberately changing how you interpret a stressful situation"},{"left":"Sensory-based strategies","right":"Quick techniques using your senses to calm your stress response in the moment"}]},{"id":"q6","type":"multiple-choice","answer":"Triggers physiological changes (like releasing endorphins and reducing stress hormones) that improve mood and resilience"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Notice which unhealthy coping habits you currently rely on","Choose one or two healthy strategies from this module to try instead","Practise them consistently, even outside of stressful moments","Adjust your approach based on what actually helps you"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-strategies-to-relieve-stress';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-team-management-fundamentals-assessment', c.id, 'Module 1: Team Management Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Clear shared goals, well-defined roles, and trust between members"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"role","acceptableAnswers":["roles","Role","Roles"]},{"id":"q4","type":"scenario","answer":"Clearly define and communicate each person\'s role and responsibilities"},{"id":"q5","type":"matching","pairs":[{"left":"Lack of communication","right":"Establish regular, structured check-ins"},{"left":"Unclear roles","right":"Define and communicate clear responsibilities"},{"left":"Low trust","right":"Invest in team-building and consistent follow-through"},{"left":"Conflict avoidance","right":"Set norms that make raising issues openly acceptable"}]},{"id":"q6","type":"multiple-choice","answer":"Regular, transparent updates that keep the whole team informed"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Set clear, shared goals","Define roles and responsibilities","Establish regular communication routines","Monitor progress and resolve problems as they arise"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-team-management-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-new-manager-assessment', c.id, 'Module 2: New Manager — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Moving from doing the work yourself to enabling and developing others to do it well"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"micromanaging","acceptableAnswers":["Micromanaging","micromanagement","Micromanagement"]},{"id":"q4","type":"scenario","answer":"Acknowledge that the relationship has changed, and set clear, consistent expectations for everyone including former peers"},{"id":"q5","type":"matching","pairs":[{"left":"Micromanaging","right":"Controlling every detail of how work gets done instead of trusting the team"},{"left":"Avoiding difficult conversations","right":"Letting performance or behaviour issues go unaddressed"},{"left":"Trying to be everyone\'s friend","right":"Prioritising being liked over making necessary decisions"},{"left":"Failing to delegate","right":"Continuing to do the team\'s work yourself instead of assigning it"}]},{"id":"q6","type":"multiple-choice","answer":"Genuinely leverage their expertise and ask for their input rather than pretending to know more than you do"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge openly that the relationship has changed","Set clear, consistent expectations for the whole team","Have individual conversations with former peers about the change","Follow through consistently to build credibility over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-new-manager';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-developing-your-team-assessment', c.id, 'Module 3: Developing your Team — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Actively support employees\' growth by identifying opportunities and helping them build relevant skills"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"performing","acceptableAnswers":["Performing"]},{"id":"q4","type":"scenario","answer":"Conduct a gap analysis to identify the specific required skills versus the team\'s current skill levels"},{"id":"q5","type":"matching","pairs":[{"left":"Forming","right":"Members are polite and getting to know one another"},{"left":"Storming","right":"Conflict emerges as roles and boundaries are tested"},{"left":"Norming","right":"The team settles into agreed ways of working together"},{"left":"Performing","right":"The team works with high trust, autonomy, and productivity"}]},{"id":"q6","type":"multiple-choice","answer":"To give regular, individual space for feedback, support, and development conversations"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Identify the skills required for the role or team\'s work","Assess the team\'s current skill levels","Pinpoint the specific gaps between the two","Select appropriate training methods to close them"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-developing-your-team';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-team-culture-assessment', c.id, 'Module 4: Team Culture — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The shared values, norms, and everyday behaviours that shape how a team actually works together"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"strengths","acceptableAnswers":["Strengths","strength","Strength"]},{"id":"q4","type":"scenario","answer":"Acknowledge and diagnose the specific underlying issues driving the negativity"},{"id":"q5","type":"matching","pairs":[{"left":"Collaborative culture","right":"Prioritises teamwork and shared decision-making"},{"left":"Competitive culture","right":"Emphasises individual performance and outperforming others"},{"left":"Hierarchical culture","right":"Decisions and structure flow clearly from senior levels down"},{"left":"Innovative culture","right":"Encourages experimentation and new ideas over strict process"}]},{"id":"q6","type":"multiple-choice","answer":"Gathering honest feedback through surveys, observation, and direct conversations"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Acknowledge and diagnose the underlying issues","Involve the team in defining a better way of working","Model the desired behaviours consistently as the leader","Reinforce and recognise positive change over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-team-culture';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-delegating-tasks-assessment', c.id, 'Module 5: Delegating Tasks — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Frees up a manager\'s time for higher-value work while developing the team\'s own capability"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"micromanaging","acceptableAnswers":["Micromanaging","micromanagement","Micromanagement"]},{"id":"q4","type":"scenario","answer":"It reflects a common reason people avoid delegating; the manager should invest short-term time in training the team so tasks can be delegated long-term"},{"id":"q5","type":"matching","pairs":[{"left":"Fear of losing control","right":"Discomfort with not overseeing every detail directly"},{"left":"Belief no one else can do it as well","right":"Underestimating the team\'s ability or potential"},{"left":"Lack of trust","right":"Doubting the team member\'s reliability or judgement"},{"left":"Perceived time cost of training others","right":"Valuing short-term speed over long-term capability"}]},{"id":"q6","type":"multiple-choice","answer":"The task\'s requirements alongside the team member\'s current skills and development goals"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Choose the right task and the right person for it","Clearly communicate the desired outcome and boundaries","Provide the resources or authority needed","Check in at agreed points without micromanaging"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-delegating-tasks';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-motivating-your-team-assessment', c.id, 'Module 6: Motivating your Team — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The internal drive that moves someone to take action toward a goal"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"intrinsic","acceptableAnswers":["Intrinsic"]},{"id":"q4","type":"scenario","answer":"A non-monetary factor like autonomy, a sense of purpose, or opportunities for growth"},{"id":"q5","type":"matching","pairs":[{"left":"Autonomy","right":"A sense of control over how you do your own work"},{"left":"Mastery / growth","right":"The opportunity to keep improving and developing skills"},{"left":"Purpose","right":"A clear sense that the work genuinely matters"},{"left":"Recognition","right":"Having your contributions genuinely seen and acknowledged"}]},{"id":"q6","type":"multiple-choice","answer":"Offering meaningful growth opportunities and consistent, specific recognition"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Understand what genuinely drives each individual team member","Align tasks with their strengths and interests where possible","Provide regular, specific recognition and feedback","Celebrate wins as a team"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-motivating-your-team';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-7-managing-remote-teams-assessment', c.id, 'Module 7: Managing Remote Teams — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Self-discipline and strong written communication skills"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"accountability","acceptableAnswers":["Accountability"]},{"id":"q4","type":"scenario","answer":"Create intentional opportunities for social connection alongside the regular work communication"},{"id":"q5","type":"matching","pairs":[{"left":"Clear written expectations","right":"Reduces ambiguity that informal office cues would otherwise fill"},{"left":"Regular check-ins","right":"Maintains alignment and catches issues early despite distance"},{"left":"Async-friendly communication","right":"Respects different time zones and working hours"},{"left":"Intentional social connection","right":"Counters the isolation remote work can create"}]},{"id":"q6","type":"multiple-choice","answer":"Over-communicate important information and choose the right channel for the message"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Set clear expectations and goals from day one","Provide the right tools and access","Schedule regular check-ins","Create opportunities for social connection with the team"]}]' FROM `courses` c WHERE c.`slug` = 'module-7-managing-remote-teams';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-8-team-dynamics-assessment', c.id, 'Module 8: Team Dynamics — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The way team members interact, behave, and relate to one another while working together"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"roles","acceptableAnswers":["Roles","role","Role"]},{"id":"q4","type":"scenario","answer":"Recognise and respect the different preferences, adapting communication and expectations without assuming one style fits everyone"},{"id":"q5","type":"matching","pairs":[{"left":"Psychological safety","right":"Members feel safe to speak up, disagree, or admit mistakes"},{"left":"Clear goals","right":"Everyone understands and is aligned on what the team is working toward"},{"left":"Complementary skills","right":"Members\' different strengths fit together to cover what\'s needed"},{"left":"Mutual accountability","right":"Members hold each other, not just a manager, responsible for results"}]},{"id":"q6","type":"multiple-choice","answer":"Encourage open communication and clarify roles where there\'s ambiguity"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Observe and diagnose the specific friction points","Have honest conversations with those involved","Clarify roles, expectations, and working agreements","Monitor and reinforce the improved dynamic over time"]}]' FROM `courses` c WHERE c.`slug` = 'module-8-team-dynamics';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-9-performance-management-assessment', c.id, 'Module 9: Performance Management — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"An ongoing process of setting expectations, giving feedback, and supporting development, not just an annual event"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"PIP","acceptableAnswers":["pip"]},{"id":"q4","type":"scenario","answer":"Stay calm, acknowledge their reaction, and continue the conversation with specific, behaviour-focused examples"},{"id":"q5","type":"matching","pairs":[{"left":"Performance Improvement Plan (PIP)","right":"A structured plan with goals and support for an underperforming employee"},{"left":"Continuous performance management","right":"Ongoing feedback and check-ins, not just an annual review"},{"left":"Managing high performers","right":"Providing growth opportunities and challenge to keep them engaged"},{"left":"Effective performance review","right":"A structured conversation grounded in specific, documented evidence"}]},{"id":"q6","type":"multiple-choice","answer":"Specific, timely, and focused on behaviour rather than character"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Clearly identify the specific performance gap","Set measurable improvement goals and a timeline","Agree on support, resources, and check-in points","Review progress and decide next steps at the deadline"]}]' FROM `courses` c WHERE c.`slug` = 'module-9-performance-management';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-10-resolving-conflict-assessment', c.id, 'Module 10: Resolving Conflict — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Miscommunication, competition for limited resources, or differing values and working styles"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"mediating","acceptableAnswers":["Mediating","mediation","Mediation"]},{"id":"q4","type":"scenario","answer":"Bring both parties together and mediate using a structured, neutral process to reach a resolution"},{"id":"q5","type":"matching","pairs":[{"left":"Avoiding","right":"Sidesteps the conflict rather than addressing it directly"},{"left":"Accommodating","right":"Gives in to the other person\'s position to keep the peace"},{"left":"Competing","right":"Pushes firmly for their own position, prioritising winning"},{"left":"Collaborating","right":"Works with the other person to find a solution that satisfies both"}]},{"id":"q6","type":"multiple-choice","answer":"Listen and acknowledge their frustration before moving into problem-solving"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Let each party share their perspective without interruption","Identify the real underlying issue behind the disagreement","Generate possible solutions together","Agree on a resolution and a plan to follow up"]}]' FROM `courses` c WHERE c.`slug` = 'module-10-resolving-conflict';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-11-letting-an-employee-go-assessment', c.id, 'Module 11: Letting an Employee Go — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Documented, persistent poor performance despite genuine support and a fair opportunity to improve"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"mitigate","acceptableAnswers":["Mitigate","reduce","Reduce"]},{"id":"q4","type":"scenario","answer":"Communicate clearly, respectfully, and directly, explaining the decision without unnecessary detail or ambiguity"},{"id":"q5","type":"matching","pairs":[{"left":"Documenting performance issues","right":"Creates a clear, fair record supporting the decision"},{"left":"Consulting HR or legal","right":"Confirms the process is compliant and reduces legal risk"},{"left":"Preparing the final conversation","right":"Ensures the news is delivered clearly and respectfully"},{"left":"Planning communication with the remaining team","right":"Protects trust and morale after the departure"}]},{"id":"q6","type":"multiple-choice","answer":"Communicate transparently and respectfully, without sharing private details about the departed employee"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Document performance issues and the support provided","Consult HR or legal for compliance","Prepare a clear, respectful final conversation","Plan how to communicate with the remaining team afterward"]}]' FROM `courses` c WHERE c.`slug` = 'module-11-letting-an-employee-go';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-time-management-fundamentals-assessment', c.id, 'Module 1: Time Management Fundamentals — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The process of consciously planning and controlling how you spend your time to work more effectively"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"tracking","acceptableAnswers":["Tracking"]},{"id":"q4","type":"scenario","answer":"Poor time management — being busy is not the same as being productive"},{"id":"q5","type":"matching","pairs":[{"left":"Constant firefighting","right":"Always reacting to urgent problems instead of planned work"},{"left":"Feeling busy without progress","right":"A full day that doesn\'t produce meaningful results"},{"left":"Chronic stress or overwhelm","right":"Persistently feeling like there\'s never enough time"},{"left":"Frequently missed deadlines","right":"Work regularly finishing later than committed to"}]},{"id":"q6","type":"multiple-choice","answer":"Prioritising tasks rather than treating every item on your list as equally urgent"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Track how you actually spend your time for a set period","Review and categorise the data you\'ve collected","Identify patterns and time-wasters","Adjust your habits based on what you\'ve found"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-time-management-fundamentals';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-goal-setting-assessment', c.id, 'Module 2: Goal Setting — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Gives you clear direction and something concrete to work toward and measure progress against"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"SMART","acceptableAnswers":["Smart"]},{"id":"q4","type":"scenario","answer":"Refine it into a specific, measurable, time-bound goal — for example, a named skill with a deadline and a way to measure improvement"},{"id":"q5","type":"matching","pairs":[{"left":"Specific","right":"Clearly defined, not vague or general"},{"left":"Measurable","right":"You can track concrete evidence of progress"},{"left":"Achievable","right":"Realistic given your resources and constraints"},{"left":"Time-bound","right":"Has a clear deadline or timeframe"}]},{"id":"q6","type":"multiple-choice","answer":"Breaking the goal into smaller milestones and building in accountability"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Define a specific, SMART goal","Break it into a plan with milestones","Track progress regularly","Adjust your approach and follow through to completion"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-goal-setting';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-3-scheduling-assessment', c.id, 'Module 3: Scheduling — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Turn your priorities and goals into concrete, planned blocks of time so they actually happen"},{"id":"q2","type":"true-false","answer":"True"},{"id":"q3","type":"fill-blank","answer":"fallacy","acceptableAnswers":["Fallacy"]},{"id":"q4","type":"scenario","answer":"Block time for the demanding, high-priority work first, and handle reactive tasks in dedicated slots"},{"id":"q5","type":"matching","pairs":[{"left":"Time blocking","right":"Dedicating a specific block of time to a specific task or type of work"},{"left":"Buffer time","right":"Leaving unscheduled space to absorb interruptions or overruns"},{"left":"Batching similar tasks","right":"Grouping similar small tasks together instead of scattering them"},{"left":"Scheduling around peak energy","right":"Placing demanding work when you\'re naturally most focused"}]},{"id":"q6","type":"multiple-choice","answer":"Break it into subtasks and reference how similar tasks have actually taken in the past"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["List your tasks and estimate the time each will take","Block time for top priorities during your peak energy periods","Add buffer time for likely interruptions","Review and adjust the schedule at the end of the day"]}]' FROM `courses` c WHERE c.`slug` = 'module-3-scheduling';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-4-prioritization-assessment', c.id, 'Module 4: Prioritization — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"The Eisenhower Matrix"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"importance","acceptableAnswers":["Importance"]},{"id":"q4","type":"scenario","answer":"Consider delegating it, or handling it briefly without letting it derail your important work"},{"id":"q5","type":"matching","pairs":[{"left":"Urgent and important","right":"Do it now"},{"left":"Important, not urgent","right":"Schedule dedicated time for it"},{"left":"Urgent, not important","right":"Delegate it if possible"},{"left":"Neither urgent nor important","right":"Eliminate or minimise it"}]},{"id":"q6","type":"multiple-choice","answer":"Fear of failure or a task feeling overwhelming"},{"id":"q7","type":"true-false","answer":"False"},{"id":"q8","type":"ordering","items":["Identify why you\'re actually avoiding the task","Break the task into smaller, manageable steps","Commit to starting for just a few minutes","Recognise or reward the progress you make"]}]' FROM `courses` c WHERE c.`slug` = 'module-4-prioritization';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-5-concentration-assessment', c.id, 'Module 5: Concentration — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Switching attention between tasks carries a real mental cost each time you switch"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"switching","acceptableAnswers":["task-switching","Switching","Task-switching"]},{"id":"q4","type":"scenario","answer":"Identify your specific distractions and take concrete steps to reduce or block them, like noise-cancelling headphones or a quiet space"},{"id":"q5","type":"matching","pairs":[{"left":"Adequate sleep","right":"Restores the mental energy needed to concentrate"},{"left":"Regular exercise","right":"Improves mood and cognitive function that support focus"},{"left":"Good hydration and nutrition","right":"Keeps energy and concentration stable through the day"},{"left":"Regular breaks","right":"Prevents the mental fatigue that builds up with sustained focus"}]},{"id":"q6","type":"multiple-choice","answer":"Aligning your most demanding tasks with the times of day you\'re naturally most alert and focused"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Identify your top sources of distraction","Remove or reduce notifications and physical clutter","Set clear focus blocks with defined start and end times","Communicate your availability to others around you"]}]' FROM `courses` c WHERE c.`slug` = 'module-5-concentration';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-6-overcoming-time-challenges-assessment', c.id, 'Module 6: Overcoming Time Challenges — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Honestly assess your current capacity before committing, and say no or renegotiate when it\'s already full"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"cycle","acceptableAnswers":["Cycle"]},{"id":"q4","type":"scenario","answer":"Review which meetings are truly necessary, decline or shorten the rest, and protect blocks of focus time"},{"id":"q5","type":"matching","pairs":[{"left":"Unsubscribing from unnecessary lists","right":"Reducing the volume of email arriving in the first place"},{"left":"Batch-processing email at set times","right":"Checking and responding to email in dedicated windows, not constantly"},{"left":"Using folders and filters","right":"Automatically sorting incoming email so priority items stand out"},{"left":"Applying a quick-action rule","right":"Dealing with very short items immediately rather than letting them pile up"}]},{"id":"q6","type":"multiple-choice","answer":"Build realistic buffer time into your planning instead of assuming everything will go perfectly"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Unsubscribe from or filter out unnecessary email","Set specific times to process email rather than checking constantly","Apply quick-action rules to short, simple items","File or archive everything else promptly"]}]' FROM `courses` c WHERE c.`slug` = 'module-6-overcoming-time-challenges';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-1-workplace-health-amp-safety-assessment', c.id, 'Module 1: Workplace Health & Safety — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Falls, being struck by an object, electrocution, and being caught in or between equipment"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"ergonomics","acceptableAnswers":["ergonomic design"]},{"id":"q4","type":"scenario","answer":"Cordon off or clearly mark the area and clean up the spill (or report it immediately for cleanup)"},{"id":"q5","type":"matching","pairs":[{"left":"Eye safety fundamentals","right":"Wearing appropriate protective eyewear when working with tools, chemicals, or debris"},{"left":"Ladder safety","right":"Maintaining three points of contact and inspecting the ladder before use"},{"left":"Office ergonomics","right":"Adjusting your chair, screen height, and posture to reduce strain during desk work"},{"left":"Preventing slips, trips and falls","right":"Keeping walkways clear, dry, and well-lit"}]},{"id":"q6","type":"multiple-choice","answer":"Keeping two hands and one foot, or two feet and one hand, in contact with the ladder at all times"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Plan the lift and check the path is clear","Get close to the load with feet shoulder-width apart","Bend your knees and keep your back straight","Lift smoothly using your legs, keeping the load close to your body"]}]' FROM `courses` c WHERE c.`slug` = 'module-1-workplace-health-amp-safety';
INSERT IGNORE INTO `assessments` (`id`, `slug`, `course_id`, `title`, `pass_mark`, `questions`) SELECT UUID(), 'module-2-workplace-violence-assessment', c.id, 'Module 2: Workplace Violence — Test Your Knowledge', 80, '[{"id":"q1","type":"multiple-choice","answer":"Any act or threat of physical violence, harassment, intimidation, or other threatening behaviour occurring at the worksite"},{"id":"q2","type":"true-false","answer":"False"},{"id":"q3","type":"fill-blank","answer":"warning","acceptableAnswers":["warning signs"]},{"id":"q4","type":"scenario","answer":"Report the specific behaviour and comments to management or security through the proper channel"},{"id":"q5","type":"matching","pairs":[{"left":"Level One","right":"Hostile, uncooperative, or resistant behaviour that hasn\'t escalated to threats"},{"left":"Level Two","right":"Explicit threats or intimidating behaviour directed at a person"},{"left":"Level Three","right":"Actual physical violence or an immediate, serious threat to safety"}]},{"id":"q6","type":"multiple-choice","answer":"Run (evacuate if possible), Hide (if you can\'t evacuate), Fight (only as a last resort)"},{"id":"q7","type":"true-false","answer":"True"},{"id":"q8","type":"ordering","items":["Ensure the scene is safe before approaching","Apply firm, direct pressure to the wound with a cloth or dressing","If bleeding doesn\'t stop, apply a tourniquet above the wound","Call for emergency medical help and monitor the person for shock"]}]' FROM `courses` c WHERE c.`slug` = 'module-2-workplace-violence';
